import subprocess, os, pty, select, sys

def run_pty(args, env):
    master, slave = pty.openpty()
    p = subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, close_fds=True, env=env)
    os.close(slave)
    out=b""
    while True:
        r,_,_=select.select([master], [], [], 0.5)
        if r:
            try:
                data=os.read(master, 4096)
                if not data:
                    break
                out+=data
            except:
                break
        else:
            if p.poll() is not None:
                try:
                    out+=os.read(master, 4096)
                except:
                    pass
                break
    p.wait()
    os.close(master)
    return out

def run_pipe(args, env):
    p=subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    return p.stdout, p.stderr, p.returncode

base_env=os.environ.copy()
if "COLORTERM" in base_env:
    del base_env["COLORTERM"]
if "PASTEL_COLOR_MODE" in base_env:
    del base_env["PASTEL_COLOR_MODE"]

for mode_env in [None, "off", "8bit", "24bit", "auto"]:
    env=base_env.copy()
    if mode_env:
        env["PASTEL_COLOR_MODE"]=mode_env
    out, err, code = run_pipe(["./executable", "format", "hex", "red"], env)
    print(f"PIPE PASTEL_COLOR_MODE={mode_env} => stdout={out!r} stderr={err!r}")

    out2 = run_pty(["./executable", "format", "hex", "red"], env)
    print(f"PTY PASTEL_COLOR_MODE={mode_env} => {out2[:200]!r}")

print("---- COLORTERM ---")
for ct in [None, "truecolor", "24bit", ""]:
    env=base_env.copy()
    if ct is not None:
        env["COLORTERM"]=ct
    else:
