            del env["COLORTERM"]
    out, err, code = run_pipe(["./executable", "format", "hex", "red"], env)
    print(f"PIPE COLORTERM={ct!r} => {out!r} {err!r}")
    out2 = run_pty(["./executable", "format", "hex", "red"], env)
    print(f"PTY COLORTERM={ct!r} => {out2[:400]!r}")

print("---- NO_COLOR? ----")
