use clap::{Parser, Subcommand, ValueEnum, ArgAction};
use std::io::{self, Read, IsTerminal};
use std::fmt;
use std::collections::{HashMap, HashSet};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ColorMode { Off, EightBit, TwentyFourBit, Auto }

impl std::str::FromStr for ColorMode {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "off" => Ok(ColorMode::Off),
            "8bit" => Ok(ColorMode::EightBit),
            "24bit" => Ok(ColorMode::TwentyFourBit),
            "auto" => Ok(ColorMode::Auto),
            other => Err(format!("invalid value '{}' for '--color-mode <mode>'\n  [possible values: 24bit, 8bit, off, auto]\n\nFor more information, try '--help'.", other)),
        }
    }
}

impl fmt::Display for ColorMode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ColorMode::Off => write!(f, "off"),
            ColorMode::EightBit => write!(f, "8bit"),
            ColorMode::TwentyFourBit => write!(f, "24bit"),
            ColorMode::Auto => write!(f, "auto"),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EnvColorMode { Off, EightBit, TwentyFourBit }

#[derive(Debug, Clone)]
struct Color {
    r: u8,
    g: u8,
    b: u8,
    alpha: f32, // 0-1
    // store original name if parsed from name, for display?
    name: Option<String>,
}

impl Color {
    fn new(r: u8, g: u8, b: u8, alpha: f32) -> Self {
        Self { r,g,b, alpha, name: None }
    }
    fn with_name(mut self, n: String) -> Self {
        self.name = Some(n);
        self
    }
    fn is_opaque(&self) -> bool {
        (self.alpha - 1.0).abs() < 1e-6 || self.alpha > 0.999999
    }
    fn to_hex(&self) -> String {
        if self.is_opaque() {
            format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
        } else {
            let a = (self.alpha * 255.0).round() as u8;
            format!("#{:02x}{:02x}{:02x}{:02x}", self.r, self.g, self.b, a)
        }
    }
    // default format for pipe: hsl without spaces, lower case? The observed: "hsl(0,100.0%,50.0%)" and "hsla(0,100.0%,70.0%,0.5)"
    fn to_default_string(&self) -> String {
        // use hsl representation without spaces? Actually we need to output hsl with no spaces, like pastel does for pipe.
        let (h,s,l) = self.to_hsl();
        if self.is_opaque() {
            format!("hsl({},{:.1}%,{:.1}%)", Self::format_hue(h), s*100.0, l*100.0)
        } else {
            format!("hsla({},{:.1}%,{:.1}%,{})", Self::format_hue(h), s*100.0, l*100.0, Self::format_alpha(self.alpha))
        }
    }
    fn format_hue(h: f32) -> String {
        // hue rounded to integer? For default string, we saw integer? e.g., hsl(0,100.0%,50.0%) hue integer, but for some colors hue may be fractional? Let's see distinct gave hsl(53,100.0%,24.7%) integer hue.
        // So hue integer rounded.
        format!("{}", h.round() as i32)
    }
    fn format_alpha(a: f32) -> String {
        // Format alpha: trim?
        // We saw 0.5, 0.502, 0.123 etc.
        // For 0.502, they gave 0.502 (3 decimals). For 0.5, 0.5 (1 decimal). For 0.123456, 0.123 (3 decimals?) Actually we saw 0.123456 gave 0.123 (rounded to 3 decimals?).
        // Let's check: rgba(255,0,0,0.123456) -> format hex #ff00001f (0x1f=31, 31/255=0.1215, rounded? Actually 0.123456*255=31.48 =>31 =>0x1f). But for format rgb, it gave "rgba(255, 0, 0, 0.123)" – 3 decimals.
        // For format hsl with alpha 0.123456: "hsla(0, 100.0%, 50.0%, 0.123)" – 3 decimals.
        // For alpha 0.5, they gave 0.5 not 0.500.
        // So we need formatting that trims trailing zeros but keeps up to 3 decimals? Let's see: alpha 0.502 gave 0.502.
        // For alpha 0? "rgba(255, 0, 0, 0)" – 0.
        // For alpha 0.100000? Might give 0.1?
        // We'll implement: round to 3 decimal places? Actually alpha from hex #ff000080 =128/255=0.50196 => 0.502 rounded to 3 decimals.
        // So format alpha: round to 3 decimals, then trim trailing zeros? Let's test: 0.5 -> 0.5 (0.500 trimmed), 0 -> 0, 0.502 -> 0.502, 0.123 ->0.123.
        // That matches.
        // Implement: format with 3 decimals, then trim zeros and possibly dot.
        let rounded = (a*1000.0).round()/1000.0;
        if (rounded - 1.0).abs() < 1e-6 {
            return "1".to_string();
        }
        // format with 3 decimals, trim
        let mut s = format!("{:.3}", rounded);
        // trim trailing zeros
        while s.contains('.') && s.ends_with('0') {
            s.pop();
        }
        if s.ends_with('.') {
            s.pop();
        }
        if s.is_empty() { s = "0".to_string(); }
        s
    }
    fn to_rgb_string(&self) -> String {
        if self.is_opaque() {
            format!("rgb({}, {}, {})", self.r, self.g, self.b)
        } else {
            format!("rgba({}, {}, {}, {})", self.r, self.g, self.b, Self::format_alpha(self.alpha))
        }
    }
    fn to_rgb_float_string(&self) -> String {
        let rf = self.r as f32 / 255.0;
        let gf = self.g as f32 / 255.0;
        let bf = self.b as f32 / 255.0;
        if self.is_opaque() {
            format!("rgb({:.3}, {:.3}, {:.3})", rf, gf, bf)
        } else {
            format!("rgba({:.3}, {:.3}, {:.3}, {})", rf, gf, bf, Self::format_alpha(self.alpha))
        }
    }
    fn to_hsl(&self) -> (f32, f32, f32) {
        // returns h 0-360, s 0-1, l 0-1
        let r = self.r as f32 / 255.0;
        let g = self.g as f32 / 255.0;
        let b = self.b as f32 / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let l = (max+min)/2.0;
        if (max-min).abs() < 1e-6 {
            return (0.0, 0.0, l);
        }
        let d = max-min;
        let s = if l>0.5 { d/(2.0-max-min) } else { d/(max+min) };
        let h = if max==r {
            (g-b)/d + if g<b {6.0} else {0.0}
        } else if max==g {
            (b-r)/d + 2.0
        } else {
            (r-g)/d + 4.0
        };
        let h = h*60.0;
        (h, s, l)
    }
    fn from_hsl(h: f32, s: f32, l: f32, alpha: f32) -> Self {
        let h = h % 360.0;
        let h = if h<0.0 { h+360.0 } else { h } / 360.0;
        let r,g,b;
        if s==0.0 {
            r=g=b=l;
        } else {
            let q = if l<0.5 { l*(1.0+s) } else { l+s - l*s };
            let p = 2.0*l - q;
            r = Self::hue_to_rgb(p,q,h+1.0/3.0);
            g = Self::hue_to_rgb(p,q,h);
            b = Self::hue_to_rgb(p,q,h-1.0/3.0);
        }
        Self::new((r*255.0).round() as u8, (g*255.0).round() as u8, (b*255.0).round() as u8, alpha)
    }
    fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
        if t<0.0 { t+=1.0; }
        if t>1.0 { t-=1.0; }
        if t<1.0/6.0 { return p + (q-p)*6.0*t; }
        if t<1.0/2.0 { return q; }
        if t<2.0/3.0 { return p + (q-p)*(2.0/3.0 - t)*6.0; }
        p
    }
    fn to_hsv(&self) -> (f32, f32, f32) {
        let r = self.r as f32 / 255.0;
        let g = self.g as f32 / 255.0;
        let b = self.b as f32 / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let v = max;
        let d = max-min;
        let s = if max==0.0 {0.0} else { d/max };
        if d==0.0 {
            return (0.0, s, v);
        }
        let h = if max==r {
            (g-b)/d + if g<b {6.0} else {0.0}
        } else if max==g {
            (b-r)/d + 2.0
        } else {
            (r-g)/d + 4.0
        };
        (h*60.0, s, v)
    }
    fn from_hsv(h: f32, s: f32, v: f32, alpha: f32) -> Self {
        let h = h % 360.0;
        let h = if h<0.0 { h+360.0 } else { h };
        let c = v*s;
        let h_prime = h/60.0;
        let x = c*(1.0-((h_prime % 2.0)-1.0).abs());
        let (r1,g1,b1) = if h_prime<1.0 { (c,x,0.0) } else if h_prime<2.0 { (x,c,0.0) } else if h_prime<3.0 { (0.0,c,x) } else if h_prime<4.0 { (0.0,x,c) } else if h_prime<5.0 { (x,0.0,c) } else { (c,0.0,x) };
        let m = v-c;
        Self::new(((r1+m)*255.0).round() as u8, ((g1+m)*255.0).round() as u8, ((b1+m)*255.0).round() as u8, alpha)
    }
    // XYZ and Lab
    fn to_linear(c: f32) -> f32 {
        if c <= 0.04045 {
            c/12.92
        } else {
            ((c+0.055)/1.055).powf(2.4)
        }
    }
    fn from_linear(c: f32) -> f32 {
        if c <= 0.0031308 {
            c*12.92
        } else {
            1.055*c.powf(1.0/2.4)-0.055
        }
    }
    fn to_xyz(&self) -> (f32, f32, f32) {
        let r = Self::to_linear(self.r as f32/255.0);
        let g = Self::to_linear(self.g as f32/255.0);
        let b = Self::to_linear(self.b as f32/255.0);
        // sRGB to XYZ D65
        let x = r*0.4124564 + g*0.3575761 + b*0.1804375;
        let y = r*0.2126729 + g*0.7151522 + b*0.0721750;
        let z = r*0.0193339 + g*0.1191920 + b*0.9503041;
        (x,y,z)
    }
    fn from_xyz(x: f32, y: f32, z: f32, alpha: f32) -> Self {
        // XYZ to linear sRGB
        let r =  x* 3.2404542 + y* -1.5371385 + z* -0.4985314;
        let g =  x* -0.9692660 + y*  1.8760108 + z*  0.0415560;
        let b =  x*  0.0556434 + y* -0.2040259 + z*  1.0572252;
        let r = Self::from_linear(r).max(0.0).min(1.0);
        let g = Self::from_linear(g).max(0.0).min(1.0);
        let b = Self::from_linear(b).max(0.0).min(1.0);
        Self::new((r*255.0).round() as u8, (g*255.0).round() as u8, (b*255.0).round() as u8, alpha)
    }
    fn to_lab(&self) -> (f32, f32, f32) {
        let (x,y,z) = self.to_xyz();
        // D65 white point
        let xn = 0.95047;
        let yn = 1.0;
        let zn = 1.08883;
        let fx = Self::lab_f(x/xn);
        let fy = Self::lab_f(y/yn);
        let fz = Self::lab_f(z/zn);
        let l = 116.0*fy - 16.0;
        let a = 500.0*(fx - fy);
        let b = 200.0*(fy - fz);
        (l,a,b)
    }
    fn lab_f(t: f32) -> f32 {
        if t > 0.008856 {
            t.powf(1.0/3.0)
        } else {
            7.787*t + 16.0/116.0
        }
    }
    fn lab_f_inv(t: f32) -> f32 {
        let t3 = t*t*t;
        if t3 > 0.008856 {
            t3
        } else {
            (t - 16.0/116.0)/7.787
        }
    }
    fn from_lab(l: f32, a: f32, b: f32, alpha: f32) -> Self {
        let yn = 1.0;
        let xn = 0.95047;
        let zn = 1.08883;
        let fy = (l+16.0)/116.0;
        let fx = fy + a/500.0;
        let fz = fy - b/200.0;
        let x = xn * Self::lab_f_inv(fx);
        let y = yn * Self::lab_f_inv(fy);
        let z = zn * Self::lab_f_inv(fz);
        Self::from_xyz(x,y,z, alpha)
    }
    fn to_lch(&self) -> (f32, f32, f32) {
        let (l,a,b) = self.to_lab();
        let c = (a*a+b*b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h<0.0 { h+=360.0; }
        (l,c,h)
    }
    fn from_lch(l: f32, c: f32, h: f32, alpha: f32) -> Self {
        let h_rad = h.to_radians();
        let a = c*h_rad.cos();
        let b = c*h_rad.sin();
        Self::from_lab(l,a,b, alpha)
    }
    // OkLab
    fn to_oklab(&self) -> (f32, f32, f32) {
        // From OkLab spec
        let r = Self::to_linear(self.r as f32/255.0);
        let g = Self::to_linear(self.g as f32/255.0);
        let b_ = Self::to_linear(self.b as f32/255.0);
        let l = 0.4122214708*r + 0.5363325363*g + 0.0514459929*b_;
        let m = 0.2119034982*r + 0.6806995451*g + 0.1073969566*b_;
        let s = 0.0883024619*r + 0.2817188376*g + 0.6299787005*b_;
        let l_ = l.cbrt();
        let m_ = m.cbrt();
        let s_ = s.cbrt();
        let L = 0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_;
        let a = 1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_;
        let b = 0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_;
        (L,a,b)
    }
    fn from_oklab(L: f32, a: f32, b: f32, alpha: f32) -> Self {
        let l_ = L + 0.3963377774*a + 0.2158037573*b;
        let m_ = L - 0.1055613458*a - 0.0638541728*b;
        let s_ = L - 0.0894841775*a - 1.2914855480*b;
        let l = l_*l_*l_;
        let m = m_*m_*m_;
        let s = s_*s_*s_;
        let r =  4.0767416621*l - 3.3077115913*m + 0.2309699292*s;
        let g = -1.2684380046*l + 2.6097574011*m - 0.3413193965*s;
        let b = -0.0041960863*l - 0.7034186147*m + 1.7076147010*s;
        let r = Self::from_linear(r).max(0.0).min(1.0);
        let g = Self::from_linear(g).max(0.0).min(1.0);
        let b = Self::from_linear(b).max(0.0).min(1.0);
        Self::new((r*255.0).round() as u8, (g*255.0).round() as u8, (b*255.0).round() as u8, alpha)
    }
    fn to_oklch(&self) -> (f32, f32, f32) {
        let (l,a,b) = self.to_oklab();
        let c = (a*a+b*b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h<0.0 { h+=360.0; }
        (l,c,h)
    }
    fn from_oklch(l: f32, c: f32, h: f32, alpha: f32) -> Self {
        let h_rad = h.to_radians();
        let a = c*h_rad.cos();
        let b = c*h_rad.sin();
        Self::from_oklab(l,a,b, alpha)
    }
    fn luminance(&self) -> f32 {
        // WCAG relative luminance
        let r = Self::to_linear(self.r as f32/255.0);
        let g = Self::to_linear(self.g as f32/255.0);
        let b = Self::to_linear(self.b as f32/255.0);
        0.2126*r + 0.7152*g + 0.0722*b
    }
    fn brightness(&self) -> f32 {
        (0.299*self.r as f32 + 0.587*self.g as f32 + 0.114*self.b as f32)/255.0
    }
    fn to_cmyk(&self) -> (f32, f32, f32, f32) {
        let r = self.r as f32/255.0;
        let g = self.g as f32/255.0;
        let b = self.b as f32/255.0;
        let k = 1.0 - r.max(g).max(b);
        if k>=1.0-1e-6 {
            return (0.0,0.0,0.0,1.0);
        }
        let c = (1.0-r-k)/(1.0-k);
        let m = (1.0-g-k)/(1.0-k);
        let y = (1.0-b-k)/(1.0-k);
        (c,m,y,k)
    }
}

// parsing helpers
fn parse_number(s: &str) -> Result<f32, String> {
    // handle percent?
    let s = s.trim();
    if s.ends_with('%') {
        let inner = &s[..s.len()-1];
        let v: f32 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse number '{}'", s))?;
        Ok(v/100.0)
    } else {
        s.parse().map_err(|_| format!("[pastel error]: Could not parse number '{}'", s))
    }
}

fn parse_alpha(s: &str) -> Result<f32, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err(format!("[pastel error]: Could not parse color ''"));
    }
    if s.ends_with('%') {
        let inner = &s[..s.len()-1];
        let v: f32 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok((v/100.0).max(0.0).min(1.0))
    } else {
        let v: f32 = s.parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        if v>1.0 {
            // For alpha >1, clamp to 1? Observed: alpha 128 => opaque
            Ok(1.0)
        } else {
            Ok(v.max(0.0).min(1.0))
        }
    }
}

fn parse_hue(s: &str) -> Result<f32, String> {
    let s = s.trim().to_lowercase();
    if s.ends_with("deg") {
        let inner = s.trim_end_matches("deg");
        let v: f32 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v)
    } else if s.ends_with("rad") {
        let inner = s.trim_end_matches("rad");
        let v: f32 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v.to_degrees())
    } else if s.ends_with("turn") {
        let inner = s.trim_end_matches("turn");
        let v: f32 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v*360.0)
    } else if s.ends_with("grad") {
        let inner = s.trim_end_matches("grad");
        let v: f32 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v*0.9)
    } else {
        s.parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))
    }
}

fn parse_color(input: &str) -> Result<Color, String> {
    let original = input;
    let s = input.trim();
    if s.is_empty() {
        return Err(format!("[pastel error]: Could not parse color ''"));
    }
    // lower case for matching, but keep original for named colors case-insensitive
    let lower = s.to_lowercase();
    // check named colors
    if let Some(hex) = named_color_hex(&lower) {
        let mut col = parse_hex(hex)?;
        col.name = Some(lower.clone());
        // If original had different case, keep parsed name lower? But for display Name: should be original? In color output, Name: red for red. For #ff0000, it shows Name: red if hex matches red? So name detection for display should be based on closest? Actually for #ff0000, it shows Name: red. So name display is based on lookup, not original parsing. So we keep name as present.
        // If input was named color, store its name.
        if named_color_hex(&lower).is_some() {
            col.name = Some(lower);
        }
        return Ok(col);
    }
    // check gray()
    if lower.starts_with("gray(") && lower.ends_with(')') {
        let inner = &s[5..s.len()-1];
        // inner may contain comma? Actually gray(0.5)
        let val_str = inner.trim();
        // handle percent or number
        if val_str.contains(',') {
            return Err(format!("[pastel error]: Could not parse color '{}'", original));
        }
        // parse as number: 0-1 or percent or >1 => white
        if val_str.ends_with('%') {
            let v = parse_number(val_str)?;
            let v = v.max(0.0).min(1.0);
            let rgb = (v*255.0).round() as u8;
            return Ok(Color::new(rgb,rgb,rgb,1.0));
        } else {
            let v: f32 = val_str.parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", original))?;
            if v<0.0 {
                return Err(format!("[pastel error]: Could not parse color '{}'", original));
            }
            let v = if v>1.0 {1.0} else {v};
            let rgb = (v*255.0).round() as u8;
            return Ok(Color::new(rgb,rgb,rgb,1.0));
        }
    }
    // check hex with # or without
    if let Some(col) = try_parse_hex(s) {
        return Ok(col);
    }
    // check comma separated rgb "119,136,153" etc
    if let Some(col) = try_parse_comma_rgb(s) {
        return Ok(col);
    }
    // check rgb(), rgba(), hsl(), hsla(), hsv(), hsva(), lab(), lch(), oklab(), oklch()
    if let Some(col) = try_parse_function(s) {
        return Ok(col);
    }
    Err(format!("[pastel error]: Could not parse color '{}'", original))
}

fn try_parse_hex(s: &str) -> Option<Color> {
    let s = s.trim();
    let hex_str = if s.starts_with('#') { &s[1..] } else { s };
    // must be only hex digits
    if !hex_str.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    match hex_str.len() {
        3 => {
            let r = u8::from_str_radix(&hex_str[0..1].repeat(2), 16).ok()?;
            let g = u8::from_str_radix(&hex_str[1..2].repeat(2), 16).ok()?;
            let b = u8::from_str_radix(&hex_str[2..3].repeat(2), 16).ok()?;
            Some(Color::new(r,g,b,1.0))
        },
        4 => {
            let r = u8::from_str_radix(&hex_str[0..1].repeat(2), 16).ok()?;
            let g = u8::from_str_radix(&hex_str[1..2].repeat(2), 16).ok()?;
            let b = u8::from_str_radix(&hex_str[2..3].repeat(2), 16).ok()?;
            let a = u8::from_str_radix(&hex_str[3..4].repeat(2), 16).ok()?;
            Some(Color::new(r,g,b,a as f32/255.0))
        },
        6 => {
            let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
            Some(Color::new(r,g,b,1.0))
        },
        8 => {
            let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
            let a = u8::from_str_radix(&hex_str[6..8], 16).ok()?;
            Some(Color::new(r,g,b,a as f32/255.0))
        },
        _ => None,
    }
}

fn parse_hex(hex: &str) -> Result<Color, String> {
    // hex is like "#rrggbb" from known list
    try_parse_hex(hex).ok_or_else(|| format!("[pastel error]: Could not parse color '{}'", hex))
}

fn try_parse_comma_rgb(s: &str) -> Option<Color> {
    // must contain commas, and no parentheses
    if s.contains('(') || s.contains(')') {
        return None;
    }
    if !s.contains(',') {
        return None;
    }
    let parts: Vec<&str> = s.split(',').collect();
    if parts.len()<3 || parts.len()>4 {
        return None;
    }
    // try parse each part: for first 3, can be number 0-255 or percent? Observed: "119,136,153" integer, also percent? Might be percent?
    // We'll parse: if contains %, percent => value*255
    // else parse float, if <=1? But for rgb values, 119 is >1, it's 0-255. If value 0-1, treat as fraction? Let's see: earlier we tested "gray(0.5)" etc but for comma rgb we saw "0,0,0,0.5" => alpha 0.5. So first three are RGB 0-255 or 0-1? "0,0,0" => black (0-255). "0,0,0,0.5" => black with alpha 0.5. So RGB parts are integers 0-255? Or maybe also 0-1? Let's support: if value contains '%', value*255/100. Else if value >1, treat as 0-255, else if 0-1, treat as 0-1 fraction? But "0,0,0" would be 0 fraction => black. "119,136,153" => >1 => 0-255. "0,0,0,0.5" => alpha 0.5 fraction.
    // Let's parse.
    let mut rgb = [0u8;3];
    for i in 0..3 {
        let p = parts[i].trim();
        if p.is_empty() { return None; }
        if p.ends_with('%') {
            let inner = &p[..p.len()-1];
            let v: f32 = inner.trim().parse().ok()?;
            let v = (v/100.0*255.0).round().max(0.0).min(255.0) as u8;
            rgb[i]=v;
        } else {
            let v: f32 = p.parse().ok()?;
            if v>1.0 {
                // treat as 0-255
                rgb[i]=v.round().max(0.0).min(255.0) as u8;
            } else {
                // fraction
                rgb[i]=(v*255.0).round().max(0.0).min(255.0) as u8;
            }
        }
    }
    let alpha = if parts.len()==4 {
        let a_str = parts[3].trim();
        // parse alpha
        if a_str.ends_with('%') {
            let inner = &a_str[..a_str.len()-1];
            let v: f32 = inner.trim().parse().ok()?;
            (v/100.0).max(0.0).min(1.0)
        } else {
            let v: f32 = a_str.parse().ok()?;
            if v>1.0 {
                // clamp to 1 as observed
                1.0
            } else {
                v.max(0.0).min(1.0)
            }
        }
    } else {
        1.0
    };
    Some(Color::new(rgb[0], rgb[1], rgb[2], alpha))
}

fn try_parse_function(s: &str) -> Option<Color> {
    let lower = s.to_lowercase();
    // find '(' and ')'
    let open = lower.find('(')?;
    let close = lower.rfind(')')?;
    if close<=open { return None; }
    let fname = lower[..open].trim();
    let inner = s[open+1..close].trim(); // keep original case for numbers? but we use lower for parsing numbers? Use original inner lowercased?
    // split inner by comma or whitespace
    // For parsing we need to handle both comma and space separated.
    // We'll first replace commas with spaces, then split whitespace, but need to keep original number strings.
    // Actually for functions like rgb(255, 0, 0) we want split by comma then further split.
    // Simpler: get tokens by splitting on both comma and whitespace and also slash?
    // For alpha handling, functions like rgb can have 4 params, or hsl can have 4.
    // We'll parse by replacing ',' with ' ' and then splitting.
    let inner_lower = inner.to_lowercase();
    // Check for slash alpha notation: we observed it fails, so we should not support slash.
    if inner_lower.contains('/') {
        // According to observed, slash notation not supported (error). So return None to cause error later? Actually we should return None so parse_color fails (which gives error).
        return None;
    }
    // tokens: split by comma or whitespace
    let mut tokens: Vec<String> = Vec::new();
    let mut current = String::new();
    for ch in inner_lower.chars() {
        if ch==',' {
            if !current.trim().is_empty() {
                tokens.push(current.trim().to_string());
            }
            current.clear();
        } else if ch.is_whitespace() {
            if !current.trim().is_empty() {
                tokens.push(current.trim().to_string());
            }
            current.clear();
        } else {
            current.push(ch);
        }
    }
    if !current.trim().is_empty() {
        tokens.push(current.trim().to_string());
    }
    // Remove empty
    tokens.retain(|t| !t.is_empty());

    match fname {
        "rgb" | "rgba" => {
            if tokens.len()<3 || tokens.len()>4 { return None; }
            let mut rgb = [0u8;3];
            for i in 0..3 {
                let t = &tokens[i];
                if t.ends_with('%') {
                    let inner = t.trim_end_matches('%');
                    let v: f32 = inner.parse().ok()?;
                    rgb[i]=(v/100.0*255.0).round().max(0.0).min(255.0) as u8;
                } else {
                    let v: f32 = t.parse().ok()?;
                    if v>1.0 {
                        rgb[i]=v.round().max(0.0).min(255.0) as u8;
                    } else {
                        // Could be fraction 0-1? For rgb, 0-1 allowed? We saw rgb-float uses same function? But rgb(0,0,0) vs rgb(1.0,0,0) we saw rgb-float gave 1.000 etc, but rgb with float 0-1? Might be treated as 0-255? Let's treat same as before: if contains '.' and <=1, treat as fraction? Actually 0.5 should be 0-255? In CSS, rgb(0.5,0,0) not typical. We'll treat >1 as 255, else fraction.
                        // If original token is like "255" => >1 => 255. If "0.5" => between 0-1 => fraction => 128.
                        // But for opaque, "rgb(255,0,0)" => 255.
                        if t.contains('.') && v<=1.0 {
                            // check if we want fraction or 0-255? For "rgb(1.000,0,0)" that was output from rgb-float, but parsing rgb-float? Actually rgb-float is output format, not input? Input rgb-float parsing may also be same as rgb? Might need to support.
                            rgb[i]=(v*255.0).round().max(0.0).min(255.0) as u8;
                        } else {
                            rgb[i]=v.round().max(0.0).min(255.0) as u8;
                        }
                    }
                }
            }
            let alpha = if tokens.len()==4 {
                let a_str = &tokens[3];
                if a_str.ends_with('%') {
                    let inner = a_str.trim_end_matches('%');
                    let v: f32 = inner.parse().ok()?;
                    (v/100.0).max(0.0).min(1.0)
                } else {
                    let v: f32 = a_str.parse().ok()?;
                    if v>1.0 {1.0} else {v.max(0.0).min(1.0)}
                }
            } else {1.0};
            Some(Color::new(rgb[0],rgb[1],rgb[2],alpha))
        },
        "hsl" | "hsla" => {
            if tokens.len()<3 || tokens.len()>4 { return None; }
            let h = parse_hue(&tokens[0]).ok()?;
            let s_str = &tokens[1];
            let l_str = &tokens[2];
            // s and l must be percent? In CSS they are percent, but we support number 0-1 or percent.
            let s_val = if s_str.ends_with('%') {
                let inner = s_str.trim_end_matches('%');
                let v: f32 = inner.parse().ok()?;
                v/100.0
            } else {
                let v: f32 = s_str.parse().ok()?;
                if v>1.0 { v/100.0 } else { v }
            };
            let l_val = if l_str.ends_with('%') {
                let inner = l_str.trim_end_matches('%');
                let v: f32 = inner.parse().ok()?;
                v/100.0
            } else {
                let v: f32 = l_str.parse().ok()?;
                if v>1.0 { v/100.0 } else { v }
