                    let v: f32 = inner.parse().ok()?;
                    v/100.0
                } else {
                    let v: f32 = a_str.parse().ok()?;
                    if v>1.0 {1.0} else {v}
                }
            } else {1.0};
            Some(Color::from_hsl(h, s_val.max(0.0).min(1.0), l_val.max(0.0).min(1.0), alpha.max(0.0).min(1.0)))
        },
        "hsv" | "hsva" => {
            if tokens.len()<3 || tokens.len()>4 { return None; }
            let h = parse_hue(&tokens[0]).ok()?;
            let s_str = &tokens[1];
            let v_str = &tokens[2];
            let s_val = if s_str.ends_with('%') {
                let inner = s_str.trim_end_matches('%');
                let v: f32 = inner.parse().ok()?;
