            let l: f32 = tokens[0].parse().ok()?;
            let a: f32 = tokens[1].parse().ok()?;
            let b: f32 = tokens[2].parse().ok()?;
            let alpha = if tokens.len()==4 {
                let a_str = &tokens[3];
