            if tokens.len()<3 || tokens.len()>4 { return None; }
            let l: f32 = tokens[0].parse().ok()?;
            let c: f32 = tokens[1].parse().ok()?;
            let h: f32 = tokens[2].parse().ok()?;
            let alpha = if tokens.len()==4 {
                let a_str = &tokens[3];
                if a_str.ends_with('%') {
                    let inner = a_str.trim_end_matches('%');
                    let v: f32 = inner.parse().ok()?;
                    v/100.0
                } else {
                    let v: f32 = a_str.parse().ok()?;
                    if v>1.0 {1.0} else {v}
                }
            } else {1.0};
            Some(Color::from_oklch(l,c,h,alpha))
        },
        _ => None,
    }
}

