// color mode detection
fn get_color_mode(cli_mode: Option<ColorMode>, force_color: bool, is_tty: bool) -> Result<(ColorModeEffective, bool), String> {
    // effective modes: Off, 8bit, 24bit
    // Also need to know if warning should be shown
    // Logic from earlier analysis:
    // Priority:
    // 1. force_color => 24bit
    // 2. cli_mode Some => use cli
    // 3. env PASTEL_COLOR_MODE
    // 4. NO_COLOR
    // 5. COLORTERM

    // For non-tty:
    //   if force_color => 24bit
    //   else if cli_mode Some => match cli: Off=>off, 8bit=>8bit,24bit=>24bit, auto=>off
    //   else => off (ignore env, NO_COLOR, COLORTERM)
    // For tty:
    //   if force_color => 24bit
    //   else if cli_mode Some => match: Off=>off, 8bit=>8bit,24bit=>24bit, auto=> check COLORTERM truecolor|24bit =>24bit else 8bit+warning
    //   else if env PASTEL_COLOR_MODE set:
    //       parse env: must be off,8bit,24bit,truecolor (case sensitive lower). If invalid => error when tty
    //       If valid => off/8bit/24bit (truecolor=>24bit)
    //   else if NO_COLOR set => off
    //   else => check COLORTERM: truecolor|24bit =>24bit else 8bit+warning

    // For pipe, we still need to handle env invalid? Observed pipe with env invalid gave off with no error. So for non-tty, env invalid ignored.

    // For tty, if env set but invalid, return error.

    if force_color {
        return Ok((ColorModeEffective::TwentyFourBit, false));
    }

    if !is_tty {
        if let Some(cli) = cli_mode {
            match cli {
                ColorMode::Off => return Ok((ColorModeEffective::Off, false)),
                ColorMode::EightBit => return Ok((ColorModeEffective::EightBit, false)),
                ColorMode::TwentyFourBit => return Ok((ColorModeEffective::TwentyFourBit, false)),
                ColorMode::Auto => return Ok((ColorModeEffective::Off, false)),
            }
        } else {
            return Ok((ColorModeEffective::Off, false));
        }
    } else {
        // tty
        if let Some(cli) = cli_mode {
            match cli {
                ColorMode::Off => return Ok((ColorModeEffective::Off, false)),
                ColorMode::EightBit => return Ok((ColorModeEffective::EightBit, false)),
                ColorMode::TwentyFourBit => return Ok((ColorModeEffective::TwentyFourBit, false)),
                ColorMode::Auto => {
                    let colorterm = std::env::var("COLORTERM").unwrap_or_default();
                    if colorterm=="truecolor" || colorterm=="24bit" {
                        return Ok((ColorModeEffective::TwentyFourBit, false));
                    } else {
                        return Ok((ColorModeEffective::EightBit, true));
                    }
                }
            }
        }
        if let Ok(env_val) = std::env::var("PASTEL_COLOR_MODE") {
            match env_val.as_str() {
                "off" => return Ok((ColorModeEffective::Off, false)),
                "8bit" => return Ok((ColorModeEffective::EightBit, false)),
                "24bit" => return Ok((ColorModeEffective::TwentyFourBit, false)),
                "truecolor" => return Ok((ColorModeEffective::TwentyFourBit, false)),
                other => {
                    // error when tty
                    return Err(format!("[pastel error]: Unknown PASTEL_COLOR_MODE value ({})", other));
                }
            }
        }
        if std::env::var("NO_COLOR").is_ok() {
            return Ok((ColorModeEffective::Off, false));
        }
        let colorterm = std::env::var("COLORTERM").unwrap_or_default();
        if colorterm=="truecolor" || colorterm=="24bit" {
            Ok((ColorModeEffective::TwentyFourBit, false))
        } else {
            Ok((ColorModeEffective::EightBit, true))
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
