                        uniq.push(col);
                    }
                }
                cols_mut = uniq;
            }
            print_colors(&cols_mut, is_tty, effective_mode);
        },
        Some(Commands::Textcolor { colors }) => {
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let out: Vec<Color> = cols.iter().map(|c| textcolor_for_bg(c)).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        Some(Commands::ToGray { colors }) => {
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let out: Vec<Color> = cols.iter().map(|c| {
                // desaturate preserving luminance: convert to lch, set chroma 0, keep lightness?
                // Actually to-gray should preserve luminance? But earlier test: to-gray red gave LCh(53,0,297) – lightness 53 (same as red's LCh lightness 53). So preserve LCh lightness.
                // For green, we had to-gray green gave LCh(46,0,297) – lightness 46 matches green's LCh lightness 46. So preserve LCh lightness, set chroma 0.
                let (l,_,_) = c.to_lch();
                Color::from_lch(l,0.0,0.0,c.alpha)
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
    }
}

fn collect_with_default(colors: Vec<String>, is_tty: bool, mode: ColorModeEffective) -> Result<Vec<Color>, String> {
    if colors.is_empty() {
        if is_tty {
            // error
            return Err(if mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
        } else {
            let lines = read_stdin_all();
            if lines.is_empty() {
                // For some commands, empty stdin with no args should exit 0 with no output (like format, color, etc). But for distinct, we return empty to generate? For simplicity, return empty vec and let caller handle? However for commands that support stdin, empty stdin should result in no output and exit 0 (as observed for format and color pipe). For those, we return empty vec and caller will print nothing and exit 0.
                // For error cases like gray, etc, they don't use this function because they don't have colors? Actually gray doesn't have colors. So for commands that have colors optional, empty stdin with no args should give empty (no output).
                // But for is_tty false, we should return parsed colors from stdin if any.
                let mut cols = Vec::new();
                for line in lines {
                    match parse_color(&line) {
                        Ok(c) => cols.push(c),
                        Err(e) => return Err(e),
                    }
                }
                Ok(cols)
            } else {
                let mut cols = Vec::new();
                for line in lines {
                    match parse_color(&line) {
                        Ok(c) => cols.push(c),
                        Err(e) => return Err(e),
                    }
                }
                Ok(cols)
            }
        }
    } else {
        let mut cols = Vec::new();
        let mut stdin_lines = Vec::new();
        let has_dash = colors.iter().any(|x| x=="-");
        if has_dash {
            stdin_lines = read_stdin_all();
        }
        let mut dash_idx = 0usize;
        for arg in colors {
            if arg=="-" {
                if dash_idx < stdin_lines.len() {
                    match parse_color(&stdin_lines[dash_idx]) {
                        Ok(c) => cols.push(c),
                        Err(e) => return Err(e),
                    }
                    dash_idx+=1;
                } else {
                    return Err(if mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
                }
            } else if arg=="pick" {
                // For commands that allow pick as color arg, we need to fail with picker error.
                // We will return a special error to be handled outside? But for simplicity, we will handle here: print checkerboard and error and exit.

                // We'll need is_tty and mode to print appropriate error. Since this function doesn't have is_tty, we will rely on caller to detect "PICK_NEEDED".

                return Err("PICK_NEEDED".to_string());
            } else {
                match parse_color(&arg) {
                    Ok(c) => cols.push(c),
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(cols)
    }
}

