fn format_color(col: &Color, fmt: &str, mode: ColorModeEffective, is_tty: bool) -> String {
    // Generate formatted string for given format type, with colorization if needed.

    let plain = match fmt {
        "rgb" => col.to_rgb_string(),
        "rgb-float" => col.to_rgb_float_string(),
        "rgb-r" => format!("{}", col.r),
        "rgb-g" => format!("{}", col.g),
        "rgb-b" => format!("{}", col.b),
        "hex" => col.to_hex(),
        "hsl" => {
            let (h,s,l) = col.to_hsl();
            if col.is_opaque() {
