impl std::str::FromStr for ColorMode {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "off" => Ok(ColorMode::Off),
            "8bit" => Ok(ColorMode::EightBit),
            "24bit" => Ok(ColorMode::TwentyFourBit),
            "auto" => Ok(ColorMode::Auto),
            other => Err(format!("invalid value '{}' for '--color-mode <mode>'\n  [possible values: 24bit, 8bit, off, auto]\n\nFor more information, try '--help'.", other)),
        }
    }
}

impl fmt::Display for ColorMode {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ColorMode::Off => write!(f, "off"),
            ColorMode::EightBit => write!(f, "8bit"),
            ColorMode::TwentyFourBit => write!(f, "24bit"),
            ColorMode::Auto => write!(f, "auto"),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
