    fn is_opaque(&self) -> bool {
        (self.alpha - 1.0).abs() < 1e-6 || self.alpha > 0.999999
    }
    fn to_hex(&self) -> String {
        if self.is_opaque() {
            format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
