        let b = self.b as f32 / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let l = (max+min)/2.0;
        if (max-min).abs() < 1e-6 {
            return (0.0, 0.0, l);
        }
        let d = max-min;
        let s = if l>0.5 { d/(2.0-max-min) } else { d/(max+min) };
        let h = if max==r {
