        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let v = max;
        let d = max-min;
        let s = if max==0.0 {0.0} else { d/max };
        if d==0.0 {
            return (0.0, s, v);
        }
        let h = if max==r {
            (g-b)/d + if g<b {6.0} else {0.0}
        } else if max==g {
