// color output helpers
fn rgb_to_ansi8(r: u8, g: u8, b: u8) -> u8 {
    // convert to 256 color approximation
    // Using standard formula: 16 + 36*R5 + 6*G5 + B5 where R5 = r/255*5, etc, plus grayscale?
    // But pastel's mapping for red: 196. Let's see known 256 colors: 16-231 are color cube, 232-255 grayscale.
    // For red #ff0000 => should be 196. Let's compute: r=5,g=0,b=0 => 16+36*5=16+180=196 correct.
    // For green #00ff00 => 16+6*5=46? Actually 16+36*0+6*5+0=46 matches earlier 46.
    // For blue #0000ff => 21.
    // So formula works.
    // However for more complex: #778899 => 67 earlier. Let's compute: 119/255*5=2.33=>2, 136*5/255=2.66=>3? 153*5/255=3. So 16+36*2+6*2+3? Wait: 16+72+12+3=103 not 67. So not simple?
    // Maybe they use different algorithm: find closest 8-bit color by distance? But for pure colors cube matches.
    // Let's test #778899 -> we got 67 earlier for ansi-8bit-value. 67 in cube is? 67 corresponds to? 67 = 16 + 36*1 +6*2+3? 16+36=52, +12=64,+3=67 yes! So r=1,g=2,b=3? That matches 119->1? Actually 119/51~2.33 floor 2? But 1 would be 0-? Let's see: cube mapping often uses intervals: 0-47 ->0, 48-115->1, 116-155->2, 156-195->3, 196-235->4, 236-255->5. Let's apply: 119 =>1? Actually 119 is between 116-155 =>2, but we got 1 for result 67. Hmm.

    // Let's try alternative: use algorithm to find closest xterm 256 color. That's more complex, but we can brute force: predefine 256 colors RGB values and find closest.

    // For simplicity, we can implement approximation by searching.

    let palette = ansi256_palette();
    let mut best = 16u8;
    let mut best_dist = f32::MAX;
    for (i, (pr,pg,pb)) in palette.iter().enumerate().skip(16) {
        let dr = *pr as f32 - r as f32;
        let dg = *pg as f32 - g as f32;
        let db = *pb as f32 - b as f32;
        let dist = dr*dr+dg*dg+db*db;
        if dist < best_dist {
            best_dist = dist;
            best = i as u8;
        }
    }
    best
}
fn ansi256_palette() -> Vec<(u8,u8,u8)> {
    let mut pal = Vec::with_capacity(256);
    // 0-15: system colors – we can approximate, but for our search we start from 16
    for i in 0..16 {
        pal.push((0,0,0)); // placeholder
    }
    // 16-231: 6x6x6 cube
    let vals = [0,95,135,175,215,255];
    for r in 0..6 {
        for g in 0..6 {
            for b in 0..6 {
                pal.push((vals[r], vals[g], vals[b]));
            }
        }
    }
    // 232-255: grayscale
    for i in 0..24 {
        let v = 8 + i*10;
        pal.push((v,v,v));
    }
    pal
}

