fn format_hsl_for_display(col: &Color) -> String {
    // For display in box, format like "hsl(0, 100.0%, 50.0%)" with spaces? In earlier box, HSL line was "hsl(0, 100.0%, 50.0%)" with spaces.
    let (h,s,l) = col.to_hsl();
    if col.is_opaque() {
