pub fn gradient(colors: &[Color], count: usize, colorspace: &str) -> Vec<Color> {
    if colors.len()<2 || count<2 { return vec![]; }
    let mut result = Vec::with_capacity(count);
    for i in 0..count {
        let t = i as f32 / (count-1) as f32;
        let scaled = t * (colors.len()-1) as f32;
        let idx = scaled.floor() as usize;
        let frac = scaled - idx as f32;
        if idx >= colors.len()-1 {
            result.push(colors.last().unwrap().clone());
        } else {
            let c1 = &colors[idx];
            let c2 = &colors[idx+1];
            let mixed = match colorspace.to_lowercase().as_str() {
                "rgb" => {
                    let r = (c1.r as f32 * (1.0-frac) + c2.r as f32 * frac).round() as u8;
                    let g = (c1.g as f32 * (1.0-frac) + c2.g as f32 * frac).round() as u8;
                    let b = (c1.b as f32 * (1.0-frac) + c2.b as f32 * frac).round() as u8;
                    let a = c1.alpha*(1.0-frac) + c2.alpha*frac;
                    Color::new(r,g,b,a)
                },
                "hsl" => {
                    let (h1,s1,l1) = c1.to_hsl();
                    let (h2,s2,l2) = c2.to_hsl();
                    let mut delta = h2 - h1;
                    if delta>180.0 { delta-=360.0; }
                    if delta<-180.0 { delta+=360.0; }
                    let h = h1 + delta*frac;
                    let s = s1*(1.0-frac)+s2*frac;
                    let l = l1*(1.0-frac)+l2*frac;
                    let a = c1.alpha*(1.0-frac)+c2.alpha*frac;
                    Color::from_hsl(h,s,l,a)
                },
                "lab" => {
                    let (l1,a1,b1_) = c1.to_lab();
                    let (l2,a2,b2_) = c2.to_lab();
                    let l = l1*(1.0-frac)+l2*frac;
                    let av = a1*(1.0-frac)+a2*frac;
                    let bv = b1_*(1.0-frac)+b2_*frac;
                    let alpha = c1.alpha*(1.0-frac)+c2.alpha*frac;
                    Color::from_lab(l,av,bv,alpha)
                },
                "lch" => {
                    let (l1,c1_,h1) = c1.to_lch();
                    let (l2,c2_,h2) = c2.to_lch();
                    let mut delta = h2 - h1;
                    if delta>180.0 { delta-=360.0; }
                    if delta<-180.0 { delta+=360.0; }
                    let h = h1 + delta*frac;
                    let l = l1*(1.0-frac)+l2*frac;
                    let c_ = c1_*(1.0-frac)+c2_*frac;
                    let alpha = c1.alpha*(1.0-frac)+c2.alpha*frac;
                    Color::from_lch(l,c_,h,alpha)
                },
                "oklab" => {
                    let (l1,a1,b1_) = c1.to_oklab();
                    let (l2,a2,b2_) = c2.to_oklab();
                    let l = l1*(1.0-frac)+l2*frac;
                    let av = a1*(1.0-frac)+a2*frac;
                    let bv = b1_*(1.0-frac)+b2_*frac;
                    let alpha = c1.alpha*(1.0-frac)+c2.alpha*frac;
