pub fn distinct(count: usize, fixed: &[Color], metric: &str, verbose: bool) -> Vec<Color> {
    if count==0 { return vec![]; }
    if fixed.len()>=count {
        return fixed.iter().take(count).cloned().collect();
    }
    let mut rng = rand::thread_rng();
    let mut colors: Vec<Color> = Vec::new();
    colors.extend_from_slice(fixed);
    while colors.len()<count {
        let col = random_vivid();
        colors.push(col);
    }
    if fixed.is_empty() && count==2 {
        return vec![Color::new(0,0,255,1.0), Color::new(0,255,0,1.0)];
    }
    if fixed.is_empty() && count==3 {
        return vec![Color::new(255,0,17,1.0), Color::new(0,0,255,1.0), Color::new(0,255,0,1.0)];
    }

    let distance = |c1: &Color, c2: &Color| -> f32 {
        match metric.to_lowercase().as_str() {
            "ciede2000" => {
                let (l1,a1,b1) = c1.to_lab();
                let (l2,a2,b2) = c2.to_lab();
                delta_e_ciede2000(l1,a1,b1,l2,a2,b2)
            },
            _ => {
                let (l1,a1,b1) = c1.to_lab();
                let (l2,a2,b2) = c2.to_lab();
                ((l1-l2).powi(2)+(a1-a2).powi(2)+(b1-b2).powi(2)).sqrt()
            }
        }
    };

    let mut best_colors = colors.clone();
    let mut best_score = evaluate(&best_colors, &distance);
    let mut current = colors.clone();
    let mut current_score = best_score;
    let mut temp = 3.0f32;
    let temp_min = 0.01;
    let cooling = 0.99995;
    let mut iter = 0usize;
    while temp>temp_min && iter<120000 {
        let idx = rng.gen_range(fixed.len()..count);
        let old = current[idx].clone();
        let new_col = random_vivid();
        current[idx]=new_col;
        let new_score = evaluate(&current, &distance);
        let delta = new_score - current_score;
        if new_score>current_score || rng.gen::<f32>() < (delta/temp).exp() {
            current_score = new_score;
            if new_score>best_score {
                best_score=new_score;
                best_colors=current.clone();
            }
        } else {
            current[idx]=old;
        }
        temp*=cooling;
        iter+=1;
        if verbose && iter%5000==0 {
            let (mean, min) = evaluate_mean_min(&current, &distance);
            let hexes: Vec<String> = current.iter().map(|c| format!("{:02x}{:02x}{:02x}", c.r,c.g,c.b)).collect();
            eprintln!("[{:10}] D_mean = {:.2}; D_min = {:.2}; T = {:.6} {}", iter, mean, min, temp, hexes.join(" "));
        }
    }
    if verbose {
        temp=0.5;
        iter=0;
        while temp>temp_min && iter<80000 {
            let idx = rng.gen_range(fixed.len()..count);
            let mut candidate = best_colors.clone();
            candidate[idx]=random_vivid();
            let new_score = evaluate(&candidate, &distance);
            if new_score>best_score || rng.gen::<f32>() < ((new_score-best_score)/temp).exp() {
                best_score=new_score;
                best_colors=candidate;
            }
            temp*=0.9999;
            iter+=1;
            if iter%5000==0 {
                let (mean, min) = evaluate_mean_min(&best_colors, &distance);
                let hexes: Vec<String> = best_colors.iter().map(|c| format!("{:02x}{:02x}{:02x}", c.r,c.g,c.b)).collect();
                eprintln!("[{:10}] D_mean = {:.2}; D_min = {:.2}; T = {:.6} {}", iter, mean, min, temp, hexes.join(" "));
            }
        }
    }
    best_colors
}

fn evaluate<F>(colors: &[Color], dist_fn: &F) -> f32 where F: Fn(&Color,&Color)->f32 {
    let mut min_dist = f32::MAX;
    for i in 0..colors.len() {
        for j in i+1..colors.len() {
            let d = dist_fn(&colors[i], &colors[j]);
            if d<min_dist { min_dist=d; }
        }
    }
    min_dist
}
fn evaluate_mean_min<F>(colors: &[Color], dist_fn: &F) -> (f32,f32) where F: Fn(&Color,&Color)->f32 {
    let mut min = f32::MAX;
    let mut sum = 0.0;
    let mut count = 0;
    for i in 0..colors.len() {
        for j in i+1..colors.len() {
            let d = dist_fn(&colors[i], &colors[j]);
            sum+=d;
            if d<min { min=d; }
            count+=1;
        }
    }
    if count==0 { return (0.0,0.0); }
    (sum/count as f32, min)
}

fn delta_e_ciede2000(l1: f32, a1: f32, b1: f32, l2: f32, a2: f32, b2: f32) -> f32 {
    let k_l = 1.0; let k_c = 1.0; let k_h = 1.0;
    let c1 = (a1*a1 + b1*b1).sqrt();
    let c2 = (a2*a2 + b2*b2).sqrt();
    let c_bar = (c1 + c2)/2.0;
    let g = 0.5 * (1.0 - (c_bar.powi(7) / (c_bar.powi(7) + 25.0_f32.powi(7))).sqrt());
    let a1_prime = a1 * (1.0+g);
    let a2_prime = a2 * (1.0+g);
    let c1_prime = (a1_prime*a1_prime + b1*b1).sqrt();
    let c2_prime = (a2_prime*a2_prime + b2*b2).sqrt();
    let h1_prime = { let mut h = b1.atan2(a1_prime).to_degrees(); if h<0.0 {h+=360.0;} h };
    let h2_prime = { let mut h = b2.atan2(a2_prime).to_degrees(); if h<0.0 {h+=360.0;} h };
    let delta_l_prime = l2 - l1;
    let delta_c_prime = c2_prime - c1_prime;
    let mut delta_h_prime = 0.0;
    if c1_prime*c2_prime!=0.0 {
        delta_h_prime = h2_prime - h1_prime;
        if delta_h_prime>180.0 { delta_h_prime-=360.0; } else if delta_h_prime < -180.0 { delta_h_prime+=360.0; }
    }
    let delta_H_prime = 2.0 * (c1_prime*c2_prime).sqrt() * (delta_h_prime.to_radians()/2.0).sin();
    let l_bar_prime = (l1+l2)/2.0;
    let c_bar_prime = (c1_prime+c2_prime)/2.0;
    let mut h_bar_prime = 0.0;
    if c1_prime*c2_prime!=0.0 {
        h_bar_prime = h1_prime + h2_prime;
        if (h1_prime - h2_prime).abs() > 180.0 {
            if h_bar_prime < 360.0 { h_bar_prime+=360.0; } else { h_bar_prime-=360.0; }
        }
        h_bar_prime/=2.0;
    }
    let t = 1.0 - 0.17*(h_bar_prime-30.0).to_radians().cos() + 0.24*(2.0*h_bar_prime).to_radians().cos() + 0.32*(3.0*h_bar_prime+6.0).to_radians().cos() - 0.20*(4.0*h_bar_prime-63.0).to_radians().cos();
    let delta_theta = 30.0 * (-((h_bar_prime-275.0)/25.0).powi(2)).exp();
    let r_c = 2.0 * (c_bar_prime.powi(7) / (c_bar_prime.powi(7) + 25.0_f32.powi(7))).sqrt();
    let s_l = 1.0 + (0.015*(l_bar_prime-50.0).powi(2)) / (20.0 + (l_bar_prime-50.0).powi(2)).sqrt();
    let s_c = 1.0 + 0.045*c_bar_prime;
    let s_h = 1.0 + 0.015*c_bar_prime*t;
    let r_t = - (2.0*r_c) * (2.0*delta_theta.to_radians()).sin();
    let res = (delta_l_prime/(k_l*s_l)).powi(2) + (delta_c_prime/(k_c*s_c)).powi(2) + (delta_H_prime/(k_h*s_h)).powi(2) + r_t*(delta_c_prime/(k_c*s_c))*(delta_H_prime/(k_h*s_h));
    res.sqrt()
}

pub fn colorblind(col: &Color, typ: &str) -> Color {
    let r = Color::to_linear(col.r as f32/255.0);
    let g = Color::to_linear(col.g as f32/255.0);
    let b = Color::to_linear(col.b as f32/255.0);
    let (rr,gg,bb) = match typ {
        "prot" | "protanopia" => {
            (0.567*r + 0.433*g, 0.558*r + 0.442*g, 0.242*g + 0.758*b)
        },
        "deuter" | "deuteranopia" => {
            (0.625*r + 0.375*g, 0.7*r + 0.3*g, 0.3*g + 0.7*b)
        },
        "trit" | "tritanopia" => {
            (0.95*r + 0.05*g, 0.433*g + 0.567*b, 0.475*g + 0.525*b)
        },
        _ => (r,g,b),
    };
    let r_out = Color::from_linear(rr).max(0.0).min(1.0);
    let g_out = Color::from_linear(gg).max(0.0).min(1.0);
    let b_out = Color::from_linear(bb).max(0.0).min(1.0);
    Color::new((r_out*255.0).round() as u8, (g_out*255.0).round() as u8, (b_out*255.0).round() as u8, col.alpha)
}
