            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| {
                let (h,s,l) = c.to_hsl();
                let ns = (s - amt).max(0.0).min(1.0);
                Color::from_hsl(h,ns,l,c.alpha)
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "lighten" => {
            let amount = sub_matches.get_one::<String>("amount").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let amt = parse_amount(&amount).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| {
                let (h,s,l) = c.to_hsl();
                let nl = (l + amt).max(0.0).min(1.0);
                Color::from_hsl(h,s,nl,c.alpha)
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "saturate" => {
            let amount = sub_matches.get_one::<String>("amount").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let amt = parse_amount(&amount).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| {
                let (h,s,l) = c.to_hsl();
                let ns = (s + amt).max(0.0).min(1.0);
                Color::from_hsl(h,ns,l,c.alpha)
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "rotate" => {
            let degrees = sub_matches.get_one::<String>("degrees").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let deg: f32 = degrees.parse().unwrap_or_else(|_| { eprintln!("[pastel error]: Could not parse number '{}'", degrees); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| {
                let (h,s,l) = c.to_hsl();
                let mut nh = (h+deg)%360.0;
                if nh<0.0 { nh+=360.0; }
                Color::from_hsl(nh,s,l,c.alpha)
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "gray" => {
            let lightness = sub_matches.get_one::<String>("lightness").unwrap().clone();
