            let clamped = l.max(0.0).min(1.0);
            let col = Color::from_hsl(0.0,0.0,clamped,1.0);
            if !is_tty { println!("{}", col.to_default_string()); } else { print_color_box(&col, effective_mode); }
        },
        "list" => {
            let sort = sub_matches.get_one::<String>("sort").unwrap().clone();
            let sort_lower = sort.to_lowercase();
            let mut colors = if sort_lower=="random" { all_named_colors() } else { distinct_colors_139() };
            use rand::seq::SliceRandom;
            match sort_lower.as_str() {
                "hue" => {
                    colors.sort_by(|a,b| {
                        let ca = parse_color(a.1).unwrap().to_lch().2;
                        let cb = parse_color(b.1).unwrap().to_lch().2;
                        ca.partial_cmp(&cb).unwrap()
                    });
                },
                "brightness" => {
                    colors.sort_by(|a,b| {
                        let ca = parse_color(a.1).unwrap().brightness();
                        let cb = parse_color(b.1).unwrap().brightness();
                        ca.partial_cmp(&cb).unwrap()
                    });
                },
                "luminance" => {
                    colors.sort_by(|a,b| {
                        let ca = parse_color(a.1).unwrap().luminance();
                        let cb = parse_color(b.1).unwrap().luminance();
                        ca.partial_cmp(&cb).unwrap()
                    });
                },
                "chroma" => {
                    colors.sort_by(|a,b| {
                        let ca = parse_color(a.1).unwrap().to_lch().1;
                        let cb = parse_color(b.1).unwrap().to_lch().1;
                        ca.partial_cmp(&cb).unwrap()
                    });
                },
                "random" => {
                    let mut rng = rand::thread_rng();
                    colors.shuffle(&mut rng);
                },
                _ => {}
            }
            if !is_tty {
                for (name,_) in colors { println!("{}", name); }
            } else {
                if effective_mode==ColorModeEffective::Off {
                    for (name,_) in colors { println!(" {:25}", name); }
                } else if effective_mode==ColorModeEffective::EightBit {
                    for (name,hex) in colors {
                        let col = parse_color(hex).unwrap();
                        let ansi = rgb_to_ansi8(col.r, col.g, col.b);
                        let fg = textcolor_for_bg(&col);
                        let fg_ansi = rgb_to_ansi8(fg.r, fg.g, fg.b);
                        println!("\x1b[38;5;{};48;5;{}m {:25}\x1b[0m", fg_ansi, ansi, name);
                    }
                } else {
                    for (name,hex) in colors {
                        let col = parse_color(hex).unwrap();
                        let fg = textcolor_for_bg(&col);
                        println!("\x1b[38;2;{};{};{};48;2;{};{};{}m {:25}\x1b[0m", fg.r, fg.g, fg.b, col.r, col.g, col.b, name);
                    }
                }
            }
        },
        "mix" => {
