#[derive(Debug, Clone)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
    pub alpha: f64,
    pub name: Option<String>,
}

impl Color {
    pub fn new(r: u8, g: u8, b: u8, alpha: f64) -> Self {
        Self { r,g,b, alpha, name: None }
    }
    pub fn is_opaque(&self) -> bool {
        (self.alpha - 1.0).abs() < 1e-6 || self.alpha > 0.9999
    }
    pub fn to_hex(&self) -> String {
        if self.is_opaque() {
            format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
        } else {
            let a = (self.alpha * 255.0).round() as u8;
            format!("#{:02x}{:02x}{:02x}{:02x}", self.r, self.g, self.b, a)
        }
    }
    pub fn to_default_string(&self) -> String {
        let (h,s,l) = self.to_hsl();
        if self.is_opaque() {
            format!("hsl({},{:.1}%,{:.1}%)", h.round() as i32, s*100.0, l*100.0)
        } else {
            format!("hsla({},{:.1}%,{:.1}%,{})", h.round() as i32, s*100.0, l*100.0, Self::format_alpha(self.alpha))
        }
    }
    pub fn to_default_string_from_hsl(h: f64, s: f64, l: f64, alpha: f64) -> String {
        if (alpha - 1.0).abs() < 1e-6 || alpha > 0.9999 {
            format!("hsl({},{:.1}%,{:.1}%)", h.round() as i32, s*100.0, l*100.0)
        } else {
            format!("hsla({},{:.1}%,{:.1}%,{})", h.round() as i32, s*100.0, l*100.0, Self::format_alpha(alpha))
        }
    }
    pub fn format_alpha(a: f64) -> String {
        let rounded = (a*1000.0).round()/1000.0;
        if (rounded - 1.0).abs() < 1e-6 { return "1".to_string(); }
        let mut s = format!("{:.3}", rounded);
        while s.contains('.') && s.ends_with('0') { s.pop(); }
        if s.ends_with('.') { s.pop(); }
        if s.is_empty() { s = "0".to_string(); }
        s
    }
    pub fn to_rgb_string(&self) -> String {
        if self.is_opaque() {
            format!("rgb({}, {}, {})", self.r, self.g, self.b)
        } else {
            format!("rgba({}, {}, {}, {})", self.r, self.g, self.b, Self::format_alpha(self.alpha))
        }
    }
    pub fn to_rgb_float_string(&self) -> String {
        let rf = self.r as f64 / 255.0;
        let gf = self.g as f64 / 255.0;
        let bf = self.b as f64 / 255.0;
        if self.is_opaque() {
            format!("rgb({:.3}, {:.3}, {:.3})", rf, gf, bf)
        } else {
            format!("rgba({:.3}, {:.3}, {:.3}, {})", rf, gf, bf, Self::format_alpha(self.alpha))
        }
    }
    pub fn to_hsl(&self) -> (f64, f64, f64) {
        let r = self.r as f64 / 255.0;
        let g = self.g as f64 / 255.0;
        let b = self.b as f64 / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let l = (max+min)/2.0;
        if (max-min).abs() < 1e-9 { return (0.0, 0.0, l); }
        let d = max-min;
        let s = if l>0.5 { d/(2.0-max-min) } else { d/(max+min) };
        let h = if max==r { (g-b)/d + if g<b {6.0} else {0.0} } else if max==g { (b-r)/d + 2.0 } else { (r-g)/d + 4.0 };
        (h*60.0, s, l)
    }
    pub fn from_hsl(h: f64, s: f64, l: f64, alpha: f64) -> Self {
        let h = h % 360.0;
        let h = if h<0.0 { h+360.0 } else { h } / 360.0;
        if s==0.0 {
            let v = (l*255.0).round() as u8;
            return Self::new(v,v,v,alpha);
        } else {
            let q = if l<0.5 { l*(1.0+s) } else { l+s - l*s };
            let p = 2.0*l - q;
            let r = Self::hue_to_rgb(p,q,h+1.0/3.0);
            let g = Self::hue_to_rgb(p,q,h);
            let b = Self::hue_to_rgb(p,q,h-1.0/3.0);
            return Self::new((r*255.0).round() as u8, (g*255.0).round() as u8, (b*255.0).round() as u8, alpha);
        }
    }
    fn hue_to_rgb(p: f64, q: f64, mut t: f64) -> f64 {
        if t<0.0 { t+=1.0; }
        if t>1.0 { t-=1.0; }
        if t<1.0/6.0 { return p + (q-p)*6.0*t; }
        if t<1.0/2.0 { return q; }
        if t<2.0/3.0 { return p + (q-p)*(2.0/3.0 - t)*6.0; }
        p
    }
    pub fn to_hsv(&self) -> (f64, f64, f64) {
        let r = self.r as f64 / 255.0;
        let g = self.g as f64 / 255.0;
        let b = self.b as f64 / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let v = max;
        let d = max-min;
        let s = if max==0.0 {0.0} else { d/max };
        if d==0.0 { return (0.0, s, v); }
        let h = if max==r { (g-b)/d + if g<b {6.0} else {0.0} } else if max==g { (b-r)/d + 2.0 } else { (r-g)/d + 4.0 };
        (h*60.0, s, v)
    }
    pub fn from_hsv(h: f64, s: f64, v: f64, alpha: f64) -> Self {
        let h = h % 360.0;
        let h = if h<0.0 { h+360.0 } else { h };
        let c = v*s;
        let h_prime = h/60.0;
        let x = c*(1.0-((h_prime % 2.0)-1.0).abs());
        let (r1,g1,b1) = if h_prime<1.0 { (c,x,0.0) } else if h_prime<2.0 { (x,c,0.0) } else if h_prime<3.0 { (0.0,c,x) } else if h_prime<4.0 { (0.0,x,c) } else if h_prime<5.0 { (x,0.0,c) } else { (c,0.0,x) };
        let m = v-c;
        Self::new(((r1+m)*255.0).round() as u8, ((g1+m)*255.0).round() as u8, ((b1+m)*255.0).round() as u8, alpha)
    }
    pub fn to_linear(c: f64) -> f64 {
        if c <= 0.04045 { c/12.92 } else { ((c+0.055)/1.055).powf(2.4) }
    }
    pub fn from_linear(c: f64) -> f64 {
        if c <= 0.0031308 { c*12.92 } else { 1.055*c.powf(1.0/2.4)-0.055 }
    }
    pub fn to_xyz(&self) -> (f64, f64, f64) {
        let r = Self::to_linear(self.r as f64/255.0);
        let g = Self::to_linear(self.g as f64/255.0);
        let b = Self::to_linear(self.b as f64/255.0);
        let x = r*0.4124564 + g*0.3575761 + b*0.1804375;
        let y = r*0.2126729 + g*0.7151522 + b*0.0721750;
        let z = r*0.0193339 + g*0.1191920 + b*0.9503041;
        (x,y,z)
    }
    pub fn from_xyz(x: f64, y: f64, z: f64, alpha: f64) -> Self {
        let r =  x* 3.2404542 + y* -1.5371385 + z* -0.4985314;
        let g =  x* -0.9692660 + y*  1.8760108 + z*  0.0415560;
        let b =  x*  0.0556434 + y* -0.2040259 + z*  1.0572252;
        let r = Self::from_linear(r).max(0.0).min(1.0);
        let g = Self::from_linear(g).max(0.0).min(1.0);
        let b = Self::from_linear(b).max(0.0).min(1.0);
        Self::new((r*255.0).round() as u8, (g*255.0).round() as u8, (b*255.0).round() as u8, alpha)
    }
    pub fn to_lab(&self) -> (f64, f64, f64) {
        let (x,y,z) = self.to_xyz();
        let xn = 0.95047;
        let yn = 1.0;
        let zn = 1.08883;
        let fx = Self::lab_f(x/xn);
        let fy = Self::lab_f(y/yn);
        let fz = Self::lab_f(z/zn);
        let l = 116.0*fy - 16.0;
        let a = 500.0*(fx - fy);
        let b = 200.0*(fy - fz);
        (l,a,b)
    }
    fn lab_f(t: f64) -> f64 {
        if t > 0.008856 { t.powf(1.0/3.0) } else { 7.787*t + 16.0/116.0 }
    }
    fn lab_f_inv(t: f64) -> f64 {
        let t3 = t*t*t;
        if t3 > 0.008856 { t3 } else { (t - 16.0/116.0)/7.787 }
    }
    pub fn from_lab(l: f64, a: f64, b: f64, alpha: f64) -> Self {
        let yn = 1.0;
        let xn = 0.95047;
        let zn = 1.08883;
        let fy = (l+16.0)/116.0;
        let fx = fy + a/500.0;
        let fz = fy - b/200.0;
        let x = xn * Self::lab_f_inv(fx);
        let y = yn * Self::lab_f_inv(fy);
        let z = zn * Self::lab_f_inv(fz);
        Self::from_xyz(x,y,z, alpha)
    }
    pub fn to_lch(&self) -> (f64, f64, f64) {
        let (l,a,b) = self.to_lab();
        let c = (a*a+b*b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h<0.0 { h+=360.0; }
        (l,c,h)
    }
    pub fn from_lch(l: f64, c: f64, h: f64, alpha: f64) -> Self {
        let h_rad = h.to_radians();
        let a = c*h_rad.cos();
        let b = c*h_rad.sin();
        Self::from_lab(l,a,b, alpha)
    }
    pub fn to_oklab(&self) -> (f64, f64, f64) {
        let r = Self::to_linear(self.r as f64/255.0);
        let g = Self::to_linear(self.g as f64/255.0);
        let b_ = Self::to_linear(self.b as f64/255.0);
        let l = 0.4122214708*r + 0.5363325363*g + 0.0514459929*b_;
        let m = 0.2119034982*r + 0.6806995451*g + 0.1073969566*b_;
        let s = 0.0883024619*r + 0.2817188376*g + 0.6299787005*b_;
        let l_ = l.cbrt();
        let m_ = m.cbrt();
        let s_ = s.cbrt();
        let L = 0.2104542553*l_ + 0.7936177850*m_ - 0.0040720468*s_;
        let a = 1.9779984951*l_ - 2.4285922050*m_ + 0.4505937099*s_;
        let b = 0.0259040371*l_ + 0.7827717662*m_ - 0.8086757660*s_;
        (L,a,b)
    }
    pub fn from_oklab(L: f64, a: f64, b: f64, alpha: f64) -> Self {
        let l_ = L + 0.3963377774*a + 0.2158037573*b;
        let m_ = L - 0.1055613458*a - 0.0638541728*b;
        let s_ = L - 0.0894841775*a - 1.2914855480*b;
        let l = l_*l_*l_;
        let m = m_*m_*m_;
        let s = s_*s_*s_;
        let r =  4.0767416621*l - 3.3077115913*m + 0.2309699292*s;
        let g = -1.2684380046*l + 2.6097574011*m - 0.3413193965*s;
        let b = -0.0041960863*l - 0.7034186147*m + 1.7076147010*s;
        let r = Self::from_linear(r).max(0.0).min(1.0);
        let g = Self::from_linear(g).max(0.0).min(1.0);
        let b = Self::from_linear(b).max(0.0).min(1.0);
        Self::new((r*255.0).round() as u8, (g*255.0).round() as u8, (b*255.0).round() as u8, alpha)
    }
    pub fn to_oklch(&self) -> (f64, f64, f64) {
        let (l,a,b) = self.to_oklab();
        let c = (a*a+b*b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h<0.0 { h+=360.0; }
        (l,c,h)
    }
    pub fn from_oklch(l: f64, c: f64, h: f64, alpha: f64) -> Self {
        let h_rad = h.to_radians();
        let a = c*h_rad.cos();
        let b = c*h_rad.sin();
        Self::from_oklab(l,a,b, alpha)
    }
    pub fn luminance(&self) -> f64 {
        let r = Self::to_linear(self.r as f64/255.0);
        let g = Self::to_linear(self.g as f64/255.0);
        let b = Self::to_linear(self.b as f64/255.0);
        0.2126*r + 0.7152*g + 0.0722*b
    }
    pub fn brightness(&self) -> f64 {
        (0.299*self.r as f64 + 0.587*self.g as f64 + 0.114*self.b as f64)/255.0
    }
    pub fn to_cmyk(&self) -> (f64, f64, f64, f64) {
        let r = self.r as f64/255.0;
        let g = self.g as f64/255.0;
        let b = self.b as f64/255.0;
        let k = 1.0 - r.max(g).max(b);
        if k>=1.0-1e-9 { return (0.0,0.0,0.0,1.0); }
        let c = (1.0-r-k)/(1.0-k);
        let m = (1.0-g-k)/(1.0-k);
        let y = (1.0-b-k)/(1.0-k);
        (c,m,y,k)
    }
}
