fn main() {
    let cli_cmd = build_cli();
    let matches = cli_cmd.get_matches();

    let is_tty = io::stdout().is_terminal();
    let force = *matches.get_one::<bool>("force-color").unwrap_or(&false);
    let cli_mode_str = matches.get_one::<String>("color-mode").map(|s| s.as_str().to_string());
    let cli_mode: Option<ColorMode> = if let Some(mode_str) = cli_mode_str {
        match mode_str.parse::<ColorMode>() {
            Ok(m) => Some(m),
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(2);
            }
        }
    } else { None };

    let (effective_mode, show_warning) = match get_color_mode(cli_mode, force, is_tty) {
        Ok(v) => v,
        Err(err_msg) => {
            eprintln!("{}", err_msg);
            std::process::exit(1);
        }
    };

    if show_warning && is_tty {
        print_warning();
    }

    let (sub_name, sub_matches) = match matches.subcommand() {
        Some(v) => v,
        None => {
            let mut cmd = build_cli();
            cmd.print_help().unwrap();
            println!();
            std::process::exit(2);
        }
    };

