            let on = sub_matches.get_one::<String>("on").map(|s| s.clone());
            let bold = *sub_matches.get_one::<bool>("bold").unwrap_or(&false);
            let italic = *sub_matches.get_one::<bool>("italic").unwrap_or(&false);
            let underline = *sub_matches.get_one::<bool>("underline").unwrap_or(&false);
            let no_newline = *sub_matches.get_one::<bool>("no-newline").unwrap_or(&false);

            let fg_col = if color_str=="-" {
                if is_tty {
