                    std::process::exit(1);
                } else {
                    let lines = read_stdin_all();
                    if lines.is_empty() {
                        eprintln!("{}", if effective_mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
                        std::process::exit(1);
                    }
                    match parse_color(&lines[0]) {
                        Ok(c) => c,
                        Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                    }
                }
            } else {
                match parse_color(&color_str) {
                    Ok(c) => c,
                    Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                }
            };
            let bg_col = if let Some(bg_str) = on {
                match parse_color(&bg_str) {
                    Ok(c) => Some(c),
                    Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                }
            } else { None };

            let output_text = if !text_strs.is_empty() {
                text_strs.join(" ")
            } else {
                read_stdin_text()
            };

            let mut ansi_codes = Vec::new();
            match effective_mode {
                ColorModeEffective::Off => {},
                ColorModeEffective::EightBit => {
                    let fg_ansi = rgb_to_ansi8(fg_col.r, fg_col.g, fg_col.b);
                    ansi_codes.push(format!("38;5;{}", fg_ansi));
                },
                ColorModeEffective::TwentyFourBit => {
                    ansi_codes.push(format!("38;2;{};{};{}", fg_col.r, fg_col.g, fg_col.b));
                },
            }
            if let Some(bg) = &bg_col {
                match effective_mode {
                    ColorModeEffective::Off => {},
                    ColorModeEffective::EightBit => {
                        let bg_ansi = rgb_to_ansi8(bg.r, bg.g, bg.b);
                        ansi_codes.push(format!("48;5;{}", bg_ansi));
                    },
                    ColorModeEffective::TwentyFourBit => {
                        ansi_codes.push(format!("48;2;{};{};{}", bg.r, bg.g, bg.b));
                    },
                }
            }
            if bold { ansi_codes.push("1".to_string()); }
            if italic { ansi_codes.push("3".to_string()); }
            if underline { ansi_codes.push("4".to_string()); }

            if effective_mode==ColorModeEffective::Off {
                if no_newline { print!("{}", output_text); } else { println!("{}", output_text); }
            } else {
                if ansi_codes.is_empty() {
                    if no_newline { print!("{}", output_text); } else { println!("{}", output_text); }
                } else {
                    let code_str = ansi_codes.join(";");
                    if no_newline {
                        print!("\x1b[{}m{}\x1b[0m", code_str, output_text);
                    } else {
                        println!("\x1b[{}m{}\x1b[0m", code_str, output_text);
                    }
                }
            }
        },
        "pick" => {
            if is_tty {
                println!("");
                for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                println!("");
            } else {
                println!("");
                for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                println!("");
            }
            if effective_mode==ColorModeEffective::Off {
                eprintln!("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
            } else {
                eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
            }
            std::process::exit(1);
        },
        "random" => {
            let strategy = sub_matches.get_one::<String>("strategy").unwrap().clone();
            let number = *sub_matches.get_one::<usize>("number").unwrap();
            let mut cols = Vec::new();
            for _ in 0..number {
                let c = match strategy.to_lowercase().as_str() {
                    "vivid" => random_vivid(),
                    "rgb" => random_rgb(),
                    "gray" => random_gray(),
                    "lch_hue" => random_lch_hue(),
                    _ => random_vivid(),
                };
                cols.push(c);
            }
            print_colors(&cols, is_tty, effective_mode);
        },
        "distinct" => {
            let count_opt = sub_matches.get_one::<String>("count").map(|s| s.clone());
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let metric = sub_matches.get_one::<String>("metric").unwrap().clone();
            let verbose = *sub_matches.get_one::<bool>("verbose").unwrap_or(&false);
            let cnt = if let Some(cnt_str) = count_opt {
                match cnt_str.parse::<usize>() {
                    Ok(n) => n,
                    Err(_) => {
                        eprintln!("[pastel error]: Could not parse number '{}'", cnt_str);
                        std::process::exit(1);
                    }
                }
            } else { 10 };
            if cnt<=1 {
                eprintln!("[pastel error]: The number of colors must be larger than one");
                std::process::exit(1);
            }
            let mut fixed: Vec<Color> = Vec::new();
            if !colors.is_empty() {
                let mut stdin_lines = Vec::new();
                let has_dash = colors.iter().any(|x| x=="-");
                if has_dash { stdin_lines = read_stdin_all(); }
                let mut dash_idx = 0usize;
                for arg in colors {
                    if arg=="-" {
                        if dash_idx < stdin_lines.len() {
                            match parse_color(&stdin_lines[dash_idx]) {
                                Ok(c) => fixed.push(c),
                                Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                            }
                            dash_idx+=1;
                        } else {
                            eprintln!("{}", if effective_mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
                            std::process::exit(1);
                        }
                    } else if arg=="pick" {
                        if is_tty {
                            println!("");
                            for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                            println!("");
                        }
                        if effective_mode==ColorModeEffective::Off {
                            eprintln!("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                        } else {
                            eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                        }
                        std::process::exit(1);
                    } else {
                        match parse_color(&arg) {
                            Ok(c) => fixed.push(c),
                            Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                        }
                    }
                }
            }
            let result = distinct(cnt, &fixed, &metric, verbose);
            if !is_tty {
                for col in &result { println!("{}", col.to_default_string()); }
            } else {
                for col in &result { print_color_box(col, effective_mode); }
            }
        },
        "format" => {
            let format_type = sub_matches.get_one::<String>("type").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = match collect_with_default(colors, is_tty, effective_mode) {
                Ok(v) => { if v.is_empty() { std::process::exit(0); } v },
                Err(e) => {
                    if e=="PICK_NEEDED" {
                        if is_tty {
                            println!("");
                            for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                            println!("");
                        }
                        if effective_mode==ColorModeEffective::Off {
                            eprintln!("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                        } else {
                            eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                        }
                        std::process::exit(1);
                    }
                    eprintln!("{}", e);
                    std::process::exit(1);
                }
            };
            for col in cols {
                let output = format_color(&col, &format_type.to_lowercase(), effective_mode, is_tty);
                if format_type.to_lowercase()=="ansi-8bit-escapecode" || format_type.to_lowercase()=="ansi-24bit-escapecode" {
                    print!("{}", output);
                } else {
                    println!("{}", output);
                }
            }
        },
        "gradient" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let number = *sub_matches.get_one::<usize>("number").unwrap();
            let colorspace = sub_matches.get_one::<String>("colorspace").unwrap().clone();
            if number<=1 {
                eprintln!("[pastel error]: The specified color count must be larger than one");
                std::process::exit(1);
            }
            if colors.len()<2 {
                eprintln!("[pastel error]: The number of color arguments must be larger than one");
                std::process::exit(1);
            }
            let mut parsed = Vec::new();
            for arg in colors {
                if arg=="pick" {
                    if is_tty {
                        println!("");
                        for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                        println!("");
                    }
                    if effective_mode==ColorModeEffective::Off {
                        eprintln!("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                    } else {
                        eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                    }
                    std::process::exit(1);
                }
                match parse_color(&arg) {
                    Ok(c) => parsed.push(c),
                    Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                }
            }
            let result = gradient(&parsed, number, &colorspace);
            print_colors(&result, is_tty, effective_mode);
        },
        "set" => {
            let property = sub_matches.get_one::<String>("property").unwrap().clone();
            let value = sub_matches.get_one::<String>("value").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let val: f64 = value.parse().unwrap_or_else(|_| { eprintln!("[pastel error]: Could not parse number '{}'", value); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let prop_lower = property.to_lowercase();
            let out: Vec<Color> = cols.iter().map(|c| {
                match prop_lower.as_str() {
                    "lightness" => Color::from_lch(val, c.to_lch().1, c.to_lch().2, c.alpha),
                    "hue" => {
                        let (l,ch,_) = c.to_lch();
                        Color::from_lch(l,ch,val,c.alpha)
                    },
                    "chroma" => {
                        let (l,_,h) = c.to_lch();
                        Color::from_lch(l,val,h,c.alpha)
                    },
                    "lab-a" => {
                        let (l,_,b) = c.to_lab();
                        Color::from_lab(l,val,b,c.alpha)
                    },
                    "lab-b" => {
                        let (l,a,_) = c.to_lab();
                        Color::from_lab(l,a,val,c.alpha)
                    },
                    "oklab-l" => {
                        let (_,a,b) = c.to_oklab();
                        Color::from_oklab(val,a,b,c.alpha)
                    },
                    "oklab-a" => {
                        let (l,_,b) = c.to_oklab();
                        Color::from_oklab(l,val,b,c.alpha)
                    },
                    "oklab-b" => {
                        let (l,a,_) = c.to_oklab();
                        Color::from_oklab(l,a,val,c.alpha)
                    },
                    "red" => Color::new(val.round().max(0.0).min(255.0) as u8, c.g, c.b, c.alpha),
                    "green" => Color::new(c.r, val.round().max(0.0).min(255.0) as u8, c.b, c.alpha),
                    "blue" => Color::new(c.r, c.g, val.round().max(0.0).min(255.0) as u8, c.alpha),
                    "hsl-hue" => {
                        let (_,s,l) = c.to_hsl();
                        Color::from_hsl(val,s,l,c.alpha)
                    },
                    "hsl-saturation" => {
                        let (h,_,l) = c.to_hsl();
                        Color::from_hsl(h,val.max(0.0).min(1.0),l,c.alpha)
                    },
                    "hsl-lightness" => {
                        let (h,s,_) = c.to_hsl();
                        Color::from_hsl(h,s,val.max(0.0).min(1.0),c.alpha)
                    },
                    "alpha" => Color::new(c.r,c.g,c.b,val.max(0.0).min(1.0)),
                    _ => c.clone(),
                }
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "sort-by" | "sort" => {
            let sort_order = sub_matches.get_one::<String>("sort-order").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let reverse = *sub_matches.get_one::<bool>("reverse").unwrap_or(&false);
            let unique = *sub_matches.get_one::<bool>("unique").unwrap_or(&false);
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let mut cols_mut = cols.clone();
            let order_lower = sort_order.to_lowercase();
            match order_lower.as_str() {
                "hue" => {
                    cols_mut.sort_by(|a,b| a.to_lch().2.partial_cmp(&b.to_lch().2).unwrap());
                },
                "brightness" => {
                    cols_mut.sort_by(|a,b| a.brightness().partial_cmp(&b.brightness()).unwrap());
                },
                "luminance" => {
                    cols_mut.sort_by(|a,b| a.luminance().partial_cmp(&b.luminance()).unwrap());
                },
                "chroma" => {
                    cols_mut.sort_by(|a,b| a.to_lch().1.partial_cmp(&b.to_lch().1).unwrap());
                },
                "random" => {
                    use rand::seq::SliceRandom;
                    let mut rng = rand::thread_rng();
                    cols_mut.shuffle(&mut rng);
                },
                _ => {}
            }
            if reverse { cols_mut.reverse(); }
            if unique {
                let mut seen = HashSet::new();
                let mut uniq = Vec::new();
                for col in cols_mut {
                    let key = (col.r, col.g, col.b);
                    if !seen.contains(&key) {
                        seen.insert(key);
                        uniq.push(col);
                    }
                }
                cols_mut = uniq;
            }
            print_colors(&cols_mut, is_tty, effective_mode);
        },
        "textcolor" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| textcolor_for_bg(c)).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "to-gray" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| {
                let (l,_,_) = c.to_lch();
                Color::from_lch(l,0.0,0.0,c.alpha)
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        _ => {}
    }
}
