fn parse_amount(s: &str) -> Result<f64, String> {
    s.parse::<f64>().map_err(|_| format!("[pastel error]: Could not parse number '{}'", s))
}

fn read_stdin_all() -> Vec<String> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap_or(0);
    input.lines().map(|l| l.trim().to_string()).filter(|l| !l.is_empty()).collect()
}

fn read_stdin_text() -> String {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap_or(0);
    input.trim_end().to_string()
}

fn collect_with_default(colors: Vec<String>, is_tty: bool, mode: ColorModeEffective) -> Result<Vec<Color>, String> {
    if colors.is_empty() {
        if is_tty {
            return Err(if mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
        } else {
            let lines = read_stdin_all();
            let mut cols = Vec::new();
            for line in lines {
                match parse_color(&line) {
                    Ok(c) => cols.push(c),
                    Err(e) => return Err(e),
                }
            }
            Ok(cols)
        }
    } else {
        let mut cols = Vec::new();
        let mut stdin_lines = Vec::new();
        let has_dash = colors.iter().any(|x| x=="-");
        if has_dash {
            stdin_lines = read_stdin_all();
        }
        let mut dash_idx = 0usize;
        for arg in colors {
            if arg=="-" {
                if dash_idx < stdin_lines.len() {
                    match parse_color(&stdin_lines[dash_idx]) {
                        Ok(c) => cols.push(c),
                        Err(e) => return Err(e),
                    }
                    dash_idx+=1;
                } else {
                    return Err(if mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
                }
            } else if arg=="pick" {
                return Err("PICK_NEEDED".to_string());
            } else {
                match parse_color(&arg) {
                    Ok(c) => cols.push(c),
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(cols)
    }
}

fn print_colors(cols: &[Color], is_tty: bool, mode: ColorModeEffective) {
    if cols.is_empty() { return; }
    if !is_tty {
        for col in cols {
            println!("{}", col.to_default_string());
        }
    } else {
        for col in cols {
            print_color_box(col, mode);
        }
    }
}

fn print_colors_hsl_direct(hsls: &[(f64,f64,f64,f64)], is_tty: bool, mode: ColorModeEffective) {
    // hsls: vec of (h,s,l,alpha)
    if !is_tty {
        for (h,s,l,a) in hsls {
            println!("{}", Color::to_default_string_from_hsl(*h,*s,*l,*a));
        }
    } else {
        // For tty, we need to create Color from hsl and then print box
        for (h,s,l,a) in hsls {
            let col = Color::from_hsl(*h,*s,*l,*a);
            print_color_box(&col, mode);
        }
    }
}

fn build_cli() -> Command {
