                .about("Display information about the given color")
                .arg(Arg::new("color").num_args(0..).value_name("color"))
        )
        .subcommand(
            Command::new("colour").about("Display information about the given color").arg(Arg::new("color").num_args(0..).value_name("color"))
        )
        .subcommand(
            Command::new("take").about("Display information about the given color").arg(Arg::new("color").num_args(0..).value_name("color"))
        )
        .subcommand(
