fn main() {
    let cli_cmd = build_cli();
    let matches = cli_cmd.get_matches();

    let is_tty = io::stdout().is_terminal();
    let force = *matches.get_one::<bool>("force-color").unwrap_or(&false);
    let cli_mode_str = matches.get_one::<String>("color-mode").map(|s| s.as_str().to_string());
    let cli_mode: Option<ColorMode> = if let Some(mode_str) = cli_mode_str {
        match mode_str.parse::<ColorMode>() {
            Ok(m) => Some(m),
            Err(e) => {
                eprintln!("{}", e);
                std::process::exit(2);
            }
        }
    } else { None };

    let (effective_mode, show_warning) = match get_color_mode(cli_mode, force, is_tty) {
        Ok(v) => v,
        Err(err_msg) => {
            eprintln!("{}", err_msg);
            std::process::exit(1);
        }
    };

    if show_warning && is_tty {
        print_warning();
    }

    let (sub_name, sub_matches) = match matches.subcommand() {
        Some(v) => v,
        None => {
            let mut cmd = build_cli();
            cmd.print_help().unwrap();
            println!();
            std::process::exit(2);
        }
    };

    match sub_name {
        "color" | "colour" | "take" | "show" | "display" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let colors_vec = match collect_with_default(colors, is_tty, effective_mode) {
                Ok(v) => { if v.is_empty() { std::process::exit(0); } v },
                Err(e) => {
                    if e=="PICK_NEEDED" {
                        if is_tty {
                            println!("");
                            for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                            println!("");
                        }
                        if effective_mode==ColorModeEffective::Off {
                            eprintln!("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                        } else {
                            eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: Could not find any external color picker tool. See 'pastel pick --help' for more information.");
                        }
                        std::process::exit(1);
                    }
                    eprintln!("{}", e);
                    std::process::exit(1);
                }
            };
            if !is_tty {
                for col in colors_vec { println!("{}", col.to_default_string()); }
            } else {
                for col in colors_vec { print_color_box(&col, effective_mode); }
            }
        },
        "colorblind" => {
            let cb_type = sub_matches.get_one::<String>("type").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let colors_vec = match collect_with_default(colors, is_tty, effective_mode) {
                Ok(v) => { if v.is_empty() { std::process::exit(0); } v },
                Err(e) => {
                    if e=="PICK_NEEDED" {
                        if is_tty {
                            println!("");
                            for _ in 0..25 { println!("   {}", "▀".repeat(45)); }
                            println!("");
                        }
