                        }
                        std::process::exit(1);
                    }
                    eprintln!("{}", e);
                    std::process::exit(1);
                }
            };
            let transformed: Vec<Color> = colors_vec.iter().map(|c| colorblind(c, &cb_type.to_lowercase())).collect();
            print_colors(&transformed, is_tty, effective_mode);
        },
        "colorcheck" => {
            println!("");
            println!("8-bit mode:");
            println!("                              ");
            for _ in 0..4 {
                print!("  ");
                for _ in 0..8 { print!("\x1b[38;5;52;48;5;52m \x1b[0m"); }
                print!("  ");
                for _ in 0..8 { print!("\x1b[38;5;23;48;5;23m \x1b[0m"); }
                print!("  ");
