                let ns = (s - amt).max(0.0).min(1.0);
                hsls.push((h,ns,l,c.alpha));
            }
            print_colors_hsl_direct(&hsls, is_tty, effective_mode);
        },
        "lighten" => {
            let amount = sub_matches.get_one::<String>("amount").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let amt = parse_amount(&amount).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let mut hsls = Vec::new();
            for c in &cols {
                let (h,s,l) = c.to_hsl();
                let nl = (l + amt).max(0.0).min(1.0);
                hsls.push((h,s,nl,c.alpha));
            }
            print_colors_hsl_direct(&hsls, is_tty, effective_mode);
        },
        "saturate" => {
            let amount = sub_matches.get_one::<String>("amount").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let amt = parse_amount(&amount).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let mut hsls = Vec::new();
            for c in &cols {
                let (h,s,l) = c.to_hsl();
                let ns = (s + amt).max(0.0).min(1.0);
                hsls.push((h,ns,l,c.alpha));
            }
            print_colors_hsl_direct(&hsls, is_tty, effective_mode);
        },
        "rotate" => {
            let degrees = sub_matches.get_one::<String>("degrees").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let deg: f64 = degrees.parse().unwrap_or_else(|_| { eprintln!("[pastel error]: Could not parse number '{}'", degrees); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let mut hsls = Vec::new();
            for c in &cols {
                let (h,s,l) = c.to_hsl();
                let mut nh = (h+deg)%360.0;
                if nh<0.0 { nh+=360.0; }
                hsls.push((nh,s,l,c.alpha));
            }
            print_colors_hsl_direct(&hsls, is_tty, effective_mode);
        },
        "gray" => {
            let lightness = sub_matches.get_one::<String>("lightness").unwrap().clone();
            let l = parse_amount(&lightness).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            let clamped = l.max(0.0).min(1.0);
            // For gray, original outputs hsl(0,0%,50%) etc, i.e., direct HSL
            if !is_tty {
                println!("{}", Color::to_default_string_from_hsl(0.0,0.0,clamped,1.0));
            } else {
                let col = Color::from_hsl(0.0,0.0,clamped,1.0);
