            let sort_lower = sort.to_lowercase();
            let mut colors = if sort_lower=="random" { all_named_colors() } else { distinct_colors_139() };
            use rand::seq::SliceRandom;
            match sort_lower.as_str() {
                "hue" => {
                    colors.sort_by(|a,b| {
                        let ca = parse_color(a.1).unwrap().to_lch().2;
