                        ca.partial_cmp(&cb).unwrap()
                    });
                },
                "random" => {
                    let mut rng = rand::thread_rng();
                    colors.shuffle(&mut rng);
                },
                _ => {}
            }
            if !is_tty {
                for (name,_) in colors { println!("{}", name); }
            } else {
                if effective_mode==ColorModeEffective::Off {
                    for (name,_) in colors { println!(" {:25}", name); }
                } else if effective_mode==ColorModeEffective::EightBit {
                    for (name,hex) in colors {
                        let col = parse_color(hex).unwrap();
                        let ansi = rgb_to_ansi8(col.r, col.g, col.b);
                        let fg = textcolor_for_bg(&col);
                        let fg_ansi = rgb_to_ansi8(fg.r, fg.g, fg.b);
                        println!("\x1b[38;5;{};48;5;{}m {:25}\x1b[0m", fg_ansi, ansi, name);
                    }
                } else {
                    for (name,hex) in colors {
                        let col = parse_color(hex).unwrap();
                        let fg = textcolor_for_bg(&col);
                        println!("\x1b[38;2;{};{};{};48;2;{};{};{}m {:25}\x1b[0m", fg.r, fg.g, fg.b, col.r, col.g, col.b, name);
