            let other_strs: Vec<String> = sub_matches.get_many::<String>("color2").map(|v| v.cloned().collect()).unwrap_or_default();
            let colorspace = sub_matches.get_one::<String>("colorspace").unwrap().clone();
            let fraction_str = sub_matches.get_one::<String>("fraction").unwrap().clone();
