                    std::process::exit(1);
                } else {
                    let lines = read_stdin_all();
                    if lines.is_empty() { eprintln!("{}", if effective_mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() }); std::process::exit(1); }
                    match parse_color(&lines[0]) {
                        Ok(c) => c,
                        Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                    }
                }
            } else {
                match parse_color(&base_str) {
                    Ok(c) => c,
                    Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                }
            };
            let mut others = Vec::new();
            if other_strs.is_empty() {
                if !is_tty {
                    let lines = read_stdin_all();
                    let start = if base_str=="-" {1} else {0};
                    for i in start..lines.len() {
                        match parse_color(&lines[i]) {
                            Ok(c) => others.push(c),
                            Err(e) => { eprintln!("{}", e); std::process::exit(1); }
                        }
                    }
                    if others.is_empty() {
                        eprintln!("{}", if effective_mode==ColorModeEffective::Off { error_no_color_arg_plain() } else { "\x1b[38;5;196m[pastel error]\x1b[0m: A color argument needs to be provided on the command line or via a pipe. Call this command again with '-h' or '--help' to get more information.".to_string() });
                        std::process::exit(1);
                    }
                }
            } else {
                let mut stdin_lines = Vec::new();
                if other_strs.iter().any(|x| x=="-") { stdin_lines = read_stdin_all(); }
                let mut dash_idx = 0usize;
                for arg in other_strs {
                    if arg=="-" {
