fn ansi256_palette() -> Vec<(u8,u8,u8)> {
    let mut pal = Vec::with_capacity(256);
    for _ in 0..16 { pal.push((0,0,0)); }
    let vals = [0,95,135,175,215,255];
    for r in 0..6 {
        for g in 0..6 {
            for b in 0..6 {
                pal.push((vals[r], vals[g], vals[b]));
            }
        }
    }
    for i in 0..24 {
        let v = 8 + i*10;
        pal.push((v,v,v));
    }
    pal
}

pub fn textcolor_for_bg(col: &Color) -> Color {
    let bg_lum = col.luminance();
    let black_lum = 0.0;
    let white_lum = 1.0;
    let contrast_black = if bg_lum>black_lum { (bg_lum+0.05)/(black_lum+0.05) } else { (black_lum+0.05)/(bg_lum+0.05) };
    let contrast_white = if white_lum>bg_lum { (white_lum+0.05)/(bg_lum+0.05) } else { (bg_lum+0.05)/(white_lum+0.05) };
    if contrast_black >= contrast_white {
        Color::new(0,0,0,1.0)
    } else {
        Color::new(255,255,255,1.0)
    }
}

pub fn find_exact_name(col: &Color) -> (String, bool) {
    for (name, hex) in crate::named::all_named_colors() {
        let c = crate::parser::try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b {
            return (name.to_string(), true);
        }
    }
    (String::new(), false)
}

pub fn find_similar_colors(col: &Color, n: usize) -> Vec<String> {
    let mut distances: Vec<(f64, String)> = Vec::new();
    for (name, hex) in crate::named::distinct_colors_139() {
        let c = crate::parser::try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b { continue; }
        let (l1,a1,b1) = col.to_lab();
        let (l2,a2,b2) = c.to_lab();
        let d = ((l1-l2).powi(2)+(a1-a2).powi(2)+(b1-b2).powi(2)).sqrt();
        distances.push((d, name.to_string()));
    }
    distances.sort_by(|a,b| a.0.partial_cmp(&b.0).unwrap());
    distances.into_iter().take(n).map(|(_,name)| name).collect()
}

pub fn format_hsl_for_display(col: &Color) -> String {
    let (h,s,l) = col.to_hsl();
    if col.is_opaque() {
        format!("hsl({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, l*100.0)
    } else {
        format!("hsla({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, l*100.0, Color::format_alpha(col.alpha))
    }
}

pub fn print_color_box(col: &Color, mode: ColorModeEffective) {
    let (exact_name, is_exact) = find_exact_name(col);
    let similar = find_similar_colors(col, 3);
    if mode==ColorModeEffective::Off {
        if is_exact {
            println!("");
            println!("  {}  Name: {: <35}", "▀".repeat(16), exact_name);
            println!("  {}  Hex: {: <35}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), col.to_hex());
            println!("  {}  RGB: {: <35}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), col.to_rgb_string());
            println!("  {}  HSL: {: <35}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), format_hsl_for_display(col));
            println!("  {}  {}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), " ".repeat(42));
            println!("  {}  Most similar:", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)));
            if !similar.is_empty() {
                for i in 0..similar.len()-1 {
                    println!("  {}         {: <30}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), similar[i]);
                }
                println!("  {}         {: <30}", "▀".repeat(16), similar[similar.len()-1]);
            }
            println!("");
        } else {
            println!("");
            println!("  {}  Hex: {: <35}", "▀".repeat(16), col.to_hex());
            println!("  {}  RGB: {: <35}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), col.to_rgb_string());
            println!("  {}  HSL: {: <35}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), format_hsl_for_display(col));
            println!("  {}  {}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), " ".repeat(42));
            println!("  {}  Most similar:", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)));
            if !similar.is_empty() {
                for i in 0..similar.len()-1 {
                    println!("  {}         {: <30}", format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2)), similar[i]);
                }
                println!("  {}         {: <30}", "▀".repeat(16), similar[similar.len()-1]);
            }
            println!("");
        }
    } else {
        if mode==ColorModeEffective::TwentyFourBit {
            print_color_box_24(col, is_exact, exact_name, similar, true);
        } else {
            print_color_box_24(col, is_exact, exact_name, similar, false);
        }
    }
}

fn print_color_box_24(col: &Color, is_exact: bool, exact_name: String, similar: Vec<String>, is_24: bool) {
    let top_border = {
        let mut s = String::new();
        s.push_str("  ");
        for i in 0..16 {
