pub fn format_color(col: &Color, fmt: &str, mode: crate::cli::ColorModeEffective, _is_tty: bool) -> String {
    let plain = match fmt {
        "rgb" => col.to_rgb_string(),
        "rgb-float" => col.to_rgb_float_string(),
        "rgb-r" => format!("{}", col.r),
        "rgb-g" => format!("{}", col.g),
        "rgb-b" => format!("{}", col.b),
        "hex" => col.to_hex(),
        "hsl" => {
            let (h,s,l) = col.to_hsl();
            if col.is_opaque() {
                format!("hsl({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, l*100.0)
            } else {
                format!("hsla({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, l*100.0, Color::format_alpha(col.alpha))
            }
        },
        "hsl-hue" => { let (h,_,_) = col.to_hsl(); format!("{}", h.round() as i32) },
        "hsl-saturation" => { let (_,s,_) = col.to_hsl(); format!("{:.4}", s) },
        "hsl-lightness" => { let (_,_,l) = col.to_hsl(); format!("{:.4}", l) },
        "hsv" => {
            let (h,s,v) = col.to_hsv();
            if col.is_opaque() {
                format!("hsv({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, v*100.0)
            } else {
                format!("hsva({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, v*100.0, Color::format_alpha(col.alpha))
            }
        },
        "hsv-hue" => { let (h,_,_) = col.to_hsv(); format!("{}", h.round() as i32) },
        "hsv-saturation" => { let (_,s,_) = col.to_hsv(); format!("{:.4}", s) },
        "hsv-value" => { let (_,_,v) = col.to_hsv(); format!("{:.4}", v) },
        "lch" => {
            let (l,c,h) = col.to_lch();
            if col.is_opaque() {
                format!("LCh({}, {}, {})", l.round() as i32, c.round() as i32, h.round() as i32)
            } else {
                format!("LCh({}, {}, {}, {})", l.round() as i32, c.round() as i32, h.round() as i32, Color::format_alpha(col.alpha))
            }
        },
        "lch-lightness" => { let (l,_,_) = col.to_lch(); format!("{:.2}", l) },
        "lch-chroma" => { let (_,c,_) = col.to_lch(); format!("{:.2}", c) },
