    }
}

pub fn gradient(colors: &[Color], count: usize, colorspace: &str) -> Vec<Color> {
    if colors.len()<2 || count<2 { return vec![]; }
    let mut result = Vec::with_capacity(count);
    for i in 0..count {
        let t = i as f64 / (count-1) as f64;
        let scaled = t * (colors.len()-1) as f64;
        let idx = scaled.floor() as usize;
        let frac = scaled - idx as f64;
        if idx >= colors.len()-1 {
            result.push(colors.last().unwrap().clone());
        } else {
            let c1 = &colors[idx];
