                        std::process::exit(1);
                    }
                    eprintln!("{}", e); std::process::exit(1);
                }
            };
            for col in cols {
                let output = format_color(&col, &format_type.to_lowercase(), effective_mode, is_tty);
                if format_type.to_lowercase()=="ansi-8bit-escapecode" || format_type.to_lowercase()=="ansi-24bit-escapecode" {
