            let colorspace = sub_matches.get_one::<String>("colorspace").unwrap().clone();
            if number<=1 { eprintln!("[pastel error]: The specified color count must be larger than one"); std::process::exit(1); }
            if colors.len()<2 { eprintln!("[pastel error]: The number of color arguments must be larger than one"); std::process::exit(1); }
            let mut parsed = Vec::new();
            for arg in colors {
                if arg=="pick" {
                    if is_tty { println!(""); for _ in 0..25 { println!("   {}", "▀".repeat(45)); } println!(""); }
                    if effective_mode==ColorModeEffective::Off { eprintln!("[pastel error]: Could not find any external color picker tool. See 'pastel pick --help' for more information."); } else { eprintln!("\x1b[38;5;196m[pastel error]\x1b[0m: Could not find any external color picker tool. See 'pastel pick --help' for more information."); }
                    std::process::exit(1);
                }
                match parse_color(&arg) { Ok(c) => parsed.push(c), Err(e) => { eprintln!("{}", e); std::process::exit(1); } }
            }
            let result = gradient(&parsed, number, &colorspace);
