                    "oklab-b" => { let (l,a,_)=c.to_oklab(); Color::from_oklab(l,a,val,c.alpha) },
                    "red" => Color::new(val.round().max(0.0).min(255.0) as u8, c.g, c.b, c.alpha),
                    "green" => Color::new(c.r, val.round().max(0.0).min(255.0) as u8, c.b, c.alpha),
                    "blue" => Color::new(c.r, c.g, val.round().max(0.0).min(255.0) as u8, c.alpha),
                    "hsl-hue" => { let (_,s,l)=c.to_hsl(); Color::from_hsl(val,s,l,c.alpha) },
                    "hsl-saturation" => { let (h,_,l)=c.to_hsl(); Color::from_hsl(h,val.max(0.0).min(1.0),l,c.alpha) },
                    "hsl-lightness" => { let (h,s,_)=c.to_hsl(); Color::from_hsl(h,s,val.max(0.0).min(1.0),c.alpha) },
                    "alpha" => Color::new(c.r,c.g,c.b,val.max(0.0).min(1.0)),
