        },
        "sort-by" | "sort" => {
            let sort_order = sub_matches.get_one::<String>("sort-order").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let reverse = *sub_matches.get_one::<bool>("reverse").unwrap_or(&false);
            let unique = *sub_matches.get_one::<bool>("unique").unwrap_or(&false);
