            let mut cols_mut = cols.clone();
            let order_lower = sort_order.to_lowercase();
            match order_lower.as_str() {
                "hue" => { cols_mut.sort_by(|a,b| a.to_lch().2.partial_cmp(&b.to_lch().2).unwrap()); },
                "brightness" => { cols_mut.sort_by(|a,b| a.brightness().partial_cmp(&b.brightness()).unwrap()); },
                "luminance" => { cols_mut.sort_by(|a,b| a.luminance().partial_cmp(&b.luminance()).unwrap()); },
                "chroma" => { cols_mut.sort_by(|a,b| a.to_lch().1.partial_cmp(&b.to_lch().1).unwrap()); },
                "random" => { use rand::seq::SliceRandom; let mut rng = rand::thread_rng(); cols_mut.shuffle(&mut rng); },
                _ => {}
            }
            if reverse { cols_mut.reverse(); }
            if unique {
                let mut seen = HashSet::new();
                let mut uniq = Vec::new();
                for col in cols_mut {
                    let key = (col.r, col.g, col.b);
                    if !seen.contains(&key) { seen.insert(key); uniq.push(col); }
                }
                cols_mut = uniq;
            }
            print_colors(&cols_mut, is_tty, effective_mode);
        },
        "textcolor" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| textcolor_for_bg(c)).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "to-gray" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| { let (l,_,_)=c.to_lch(); Color::from_lch(l,0.0,0.0,c.alpha) }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        _ => {}
    }
}
