                return Err("PICK_NEEDED".to_string());
            } else {
                match parse_color(&arg) {
                    Ok(c) => cols.push(c),
                    Err(e) => return Err(e),
                }
            }
        }
        Ok(cols)
    }
}

fn print_colors(cols: &[Color], is_tty: bool, mode: ColorModeEffective) {
    if cols.is_empty() { return; }
    if !is_tty {
        for col in cols {
            println!("{}", col.to_default_string());
        }
    } else {
        for col in cols {
            print_color_box(col, mode);
        }
