            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let val: f64 = value.parse().unwrap_or_else(|_| { eprintln!("[pastel error]: Could not parse number '{}'", value); std::process::exit(1); });
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let prop_lower = property.to_lowercase();
            let out: Vec<Color> = cols.iter().map(|c| {
                match prop_lower.as_str() {
                    "lightness" => Color::from_lch(val, c.to_lch().1, c.to_lch().2, c.alpha),
                    "hue" => { let (l,ch,_)=c.to_lch(); Color::from_lch(l,ch,val,c.alpha) },
                    "chroma" => { let (l,_,h)=c.to_lch(); Color::from_lch(l,val,h,c.alpha) },
                    "lab-a" => { let (l,_,b)=c.to_lab(); Color::from_lab(l,val,b,c.alpha) },
                    "lab-b" => { let (l,a,_)=c.to_lab(); Color::from_lab(l,a,val,c.alpha) },
                    "oklab-l" => { let (_,a,b)=c.to_oklab(); Color::from_oklab(val,a,b,c.alpha) },
                    "oklab-a" => { let (l,_,b)=c.to_oklab(); Color::from_oklab(l,val,b,c.alpha) },
                    "oklab-b" => { let (l,a,_)=c.to_oklab(); Color::from_oklab(l,a,val,c.alpha) },
                    "red" => Color::new(val.round().max(0.0).min(255.0) as u8, c.g, c.b, c.alpha),
                    "green" => Color::new(c.r, val.round().max(0.0).min(255.0) as u8, c.b, c.alpha),
                    "blue" => Color::new(c.r, c.g, val.round().max(0.0).min(255.0) as u8, c.alpha),
                    "hsl-hue" => { let (_,s,l)=c.to_hsl(); Color::from_hsl(val,s,l,c.alpha) },
                    "hsl-saturation" => { let (h,_,l)=c.to_hsl(); Color::from_hsl(h,val.max(0.0).min(1.0),l,c.alpha) },
                    "hsl-lightness" => { let (h,s,_)=c.to_hsl(); Color::from_hsl(h,s,val.max(0.0).min(1.0),c.alpha) },
                    "alpha" => Color::new(c.r,c.g,c.b,val.max(0.0).min(1.0)),
                    _ => c.clone(),
                }
            }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "sort-by" | "sort" => {
            let sort_order = sub_matches.get_one::<String>("sort-order").unwrap().clone();
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let reverse = *sub_matches.get_one::<bool>("reverse").unwrap_or(&false);
            let unique = *sub_matches.get_one::<bool>("unique").unwrap_or(&false);
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let mut cols_mut = cols.clone();
            let order_lower = sort_order.to_lowercase();
            match order_lower.as_str() {
                "hue" => { cols_mut.sort_by(|a,b| a.to_lch().2.partial_cmp(&b.to_lch().2).unwrap()); },
                "brightness" => { cols_mut.sort_by(|a,b| a.brightness().partial_cmp(&b.brightness()).unwrap()); },
                "luminance" => { cols_mut.sort_by(|a,b| a.luminance().partial_cmp(&b.luminance()).unwrap()); },
                "chroma" => { cols_mut.sort_by(|a,b| a.to_lch().1.partial_cmp(&b.to_lch().1).unwrap()); },
                "random" => { use rand::seq::SliceRandom; let mut rng = rand::thread_rng(); cols_mut.shuffle(&mut rng); },
                _ => {}
            }
            if reverse { cols_mut.reverse(); }
            if unique {
                let mut seen = HashSet::new();
                let mut uniq = Vec::new();
                for col in cols_mut {
                    let key = (col.r, col.g, col.b);
                    if !seen.contains(&key) { seen.insert(key); uniq.push(col); }
                }
                cols_mut = uniq;
            }
            print_colors(&cols_mut, is_tty, effective_mode);
        },
        "textcolor" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| textcolor_for_bg(c)).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        "to-gray" => {
            let colors: Vec<String> = sub_matches.get_many::<String>("color").map(|v| v.cloned().collect()).unwrap_or_default();
            let cols = collect_with_default(colors, is_tty, effective_mode).unwrap_or_else(|e| { eprintln!("{}", e); std::process::exit(1); });
            if cols.is_empty() { std::process::exit(0); }
            let out: Vec<Color> = cols.iter().map(|c| { let (l,_,_)=c.to_lch(); Color::from_lch(l,0.0,0.0,c.alpha) }).collect();
            print_colors(&out, is_tty, effective_mode);
        },
        _ => {}
    }
}
