use crate::color::Color;

fn parse_number_percent(s: &str) -> Result<f64, String> {
    let s = s.trim();
    if s.ends_with('%') {
        let inner = &s[..s.len()-1];
        let v: f64 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse number '{}'", s))?;
        Ok(v/100.0)
    } else {
        s.parse().map_err(|_| format!("[pastel error]: Could not parse number '{}'", s))
    }
}

pub fn parse_hue(s: &str) -> Result<f64, String> {
    let s = s.trim().to_lowercase();
    if s.ends_with("deg") {
        let inner = s.trim_end_matches("deg");
        let v: f64 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v)
    } else if s.ends_with("rad") {
        let inner = s.trim_end_matches("rad");
        let v: f64 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v.to_degrees())
    } else if s.ends_with("turn") {
        let inner = s.trim_end_matches("turn");
        let v: f64 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v*360.0)
    } else if s.ends_with("grad") {
        let inner = s.trim_end_matches("grad");
        let v: f64 = inner.trim().parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))?;
        Ok(v*0.9)
    } else {
        s.parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", s))
    }
}

pub fn parse_color(input: &str) -> Result<Color, String> {
    let original = input;
    let s = input.trim();
    if s.is_empty() {
        return Err(format!("[pastel error]: Could not parse color ''"));
    }
    let lower = s.to_lowercase();
    if let Some(hex) = crate::named::named_color_hex(&lower) {
        let mut col = try_parse_hex(hex).ok_or_else(|| format!("[pastel error]: Could not parse color '{}'", original))?;
        col.name = Some(lower);
        return Ok(col);
    }
    if lower.starts_with("gray(") && lower.ends_with(')') {
        let inner = &s[5..s.len()-1];
        let val_str = inner.trim();
        if val_str.contains(',') {
            return Err(format!("[pastel error]: Could not parse color '{}'", original));
        }
        if val_str.ends_with('%') {
            let v = parse_number_percent(val_str).map_err(|_| format!("[pastel error]: Could not parse color '{}'", original))?;
            let v = v.max(0.0).min(1.0);
            let rgb = (v*255.0).round() as u8;
            return Ok(Color::new(rgb,rgb,rgb,1.0));
        } else {
            let v: f64 = val_str.parse().map_err(|_| format!("[pastel error]: Could not parse color '{}'", original))?;
            if v<0.0 {
                return Err(format!("[pastel error]: Could not parse color '{}'", original));
            }
            let v = if v>1.0 {1.0} else {v};
            let rgb = (v*255.0).round() as u8;
            return Ok(Color::new(rgb,rgb,rgb,1.0));
        }
    }
    if let Some(col) = try_parse_hex(s) {
        return Ok(col);
    }
    if let Some(col) = try_parse_comma_rgb(s) {
        return Ok(col);
    }
    if let Some(col) = try_parse_function(s) {
        return Ok(col);
    }
    Err(format!("[pastel error]: Could not parse color '{}'", original))
}

pub fn try_parse_hex(s: &str) -> Option<Color> {
    let s = s.trim();
    let hex_str = if s.starts_with('#') { &s[1..] } else { s };
    if !hex_str.chars().all(|c| c.is_ascii_hexdigit()) { return None; }
    match hex_str.len() {
        3 => {
            let r = u8::from_str_radix(&hex_str[0..1].repeat(2), 16).ok()?;
            let g = u8::from_str_radix(&hex_str[1..2].repeat(2), 16).ok()?;
            let b = u8::from_str_radix(&hex_str[2..3].repeat(2), 16).ok()?;
            Some(Color::new(r,g,b,1.0))
        },
        4 => {
            let r = u8::from_str_radix(&hex_str[0..1].repeat(2), 16).ok()?;
            let g = u8::from_str_radix(&hex_str[1..2].repeat(2), 16).ok()?;
            let b = u8::from_str_radix(&hex_str[2..3].repeat(2), 16).ok()?;
            let a = u8::from_str_radix(&hex_str[3..4].repeat(2), 16).ok()?;
            Some(Color::new(r,g,b,a as f64/255.0))
        },
        6 => {
            let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
            Some(Color::new(r,g,b,1.0))
        },
        8 => {
            let r = u8::from_str_radix(&hex_str[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex_str[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex_str[4..6], 16).ok()?;
            let a = u8::from_str_radix(&hex_str[6..8], 16).ok()?;
            Some(Color::new(r,g,b,a as f64/255.0))
        },
        _ => None,
    }
}

