                    let v: f64 = inner.parse().ok()?;
                    v/100.0
                } else {
                    let v: f64 = a_str.parse().ok()?;
                    if v>1.0 {1.0} else {v}
                }
            } else {1.0};
            Some(Color::from_oklch(l,c,h,alpha))
        },
        _ => None,
    }
}
