    pub fn new(r: u8, g: u8, b: u8, alpha: f64) -> Self {
        Self { r,g,b, alpha, name: None }
    }
    pub fn is_opaque(&self) -> bool {
        (self.alpha - 1.0).abs() < 1e-6 || self.alpha > 0.9999
    }
    pub fn to_hex(&self) -> String {
        if self.is_opaque() {
            format!("#{:02x}{:02x}{:02x}", self.r, self.g, self.b)
        } else {
            let a = (self.alpha * 255.0).round() as u8;
            format!("#{:02x}{:02x}{:02x}{:02x}", self.r, self.g, self.b, a)
        }
    }
    pub fn to_default_string(&self) -> String {
        let (h,s,l) = self.to_hsl();
        if self.is_opaque() {
            format!("hsl({},{:.1}%,{:.1}%)", h.round() as i32, s*100.0, l*100.0)
        } else {
            format!("hsla({},{:.1}%,{:.1}%,{})", h.round() as i32, s*100.0, l*100.0, Self::format_alpha(self.alpha))
        }
    }
    pub fn to_default_string_from_hsl(h: f64, s: f64, l: f64, alpha: f64) -> String {
        if alpha>=0.9999 {
            format!("hsl({},{:.1}%,{:.1}%)", h.round() as i32, s*100.0, l*100.0)
        } else {
            format!("hsla({},{:.1}%,{:.1}%,{})", h.round() as i32, s*100.0, l*100.0, Self::format_alpha(alpha))
        }
    }
    pub fn format_alpha(a: f64) -> String {
        let rounded = (a*1000.0).round()/1000.0;
        if (rounded - 1.0).abs() < 1e-6 { return "1".to_string(); }
        let mut s = format!("{:.3}", rounded);
        while s.contains('.') && s.ends_with('0') { s.pop(); }
        if s.ends_with('.') { s.pop(); }
        if s.is_empty() { s = "0".to_string(); }
        s
    }
    pub fn to_rgb_string(&self) -> String {
        if self.is_opaque() {
            format!("rgb({}, {}, {})", self.r, self.g, self.b)
        } else {
            format!("rgba({}, {}, {}, {})", self.r, self.g, self.b, Self::format_alpha(self.alpha))
        }
    }
    pub fn to_rgb_float_string(&self) -> String {
        let rf = self.r as f64 / 255.0;
        let gf = self.g as f64 / 255.0;
        let bf = self.b as f64 / 255.0;
        if self.is_opaque() {
            format!("rgb({:.3}, {:.3}, {:.3})", rf, gf, bf)
        } else {
            format!("rgba({:.3}, {:.3}, {:.3}, {})", rf, gf, bf, Self::format_alpha(self.alpha))
        }
    }
    pub fn to_hsl(&self) -> (f64, f64, f64) {
        let r = self.r as f64 / 255.0;
        let g = self.g as f64 / 255.0;
        let b = self.b as f64 / 255.0;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let l = (max+min)/2.0;
        if (max-min).abs() < 1e-9 { return (0.0, 0.0, l); }
        let d = max-min;
        let s = if l>0.5 { d/(2.0-max-min) } else { d/(max+min) };
        let h = if max==r { (g-b)/d + if g<b {6.0} else {0.0} } else if max==g { (b-r)/d + 2.0 } else { (r-g)/d + 4.0 };
        (h*60.0, s, l)
    }
