import pty, os, subprocess, select
def run_pty(args, env):
    master, slave = pty.openpty()
    p=subprocess.Popen(args, stdin=slave, stdout=slave, stderr=slave, close_fds=True, env=env)
    os.close(slave)
    out=b""
    while True:
        import select as sel
        r,_,_=sel.select([master], [], [], 0.5)
        if r:
            try:
                data=os.read(master, 8192)
                if not data:
                    break
                out+=data
            except:
                break
        else:
            if p.poll() is not None:
                try:
                    out+=os.read(master, 8192)
                except:
                    pass
                break
    p.wait()
