                        best_name=n.to_string();
                    }
                }
                best_name
            }
        },
        _ => col.to_hex(),
    };

    match mode {
        crate::cli::ColorModeEffective::Off => plain,
        crate::cli::ColorModeEffective::EightBit => {
            if fmt=="ansi-8bit-value" || fmt=="ansi-8bit-escapecode" || fmt=="ansi-24bit-escapecode" {
