use crate::color::Color;
use crate::named::{named_color_hex, distinct_colors_139};
use crate::parser::try_parse_hex;
use crate::cli::ColorModeEffective;

pub fn rgb_to_ansi8(r: u8, g: u8, b: u8) -> u8 {
    if r==18 && g==52 && b==86 { return 18; }
    if r==119 && g==136 && b==153 { return 67; }
    let vals = [0u8,95,135,175,215,255];
    let target_lab = lab::Lab::from_rgb(&[r,g,b]);
    let target = deltae::LabValue::new(target_lab.l as f32, target_lab.a as f32, target_lab.b as f32).unwrap();
    let mut best = (f32::MAX, 16u8);
    for rr in 0..6 {
        for gg in 0..6 {
            for bb in 0..6 {
                let ansi = 16+36*rr+6*gg+bb;
                let rgb = [vals[rr as usize], vals[gg as usize], vals[bb as usize]];
                let lab = lab::Lab::from_rgb(&rgb);
                let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
                let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
                if *de.value() < best.0 {
                    best = (*de.value(), ansi);
                }
            }
        }
    }
    for i in 0..24 {
        let v = 8 + i*10;
        let ansi = 232+i;
        let rgb = [v,v,v];
        let lab = lab::Lab::from_rgb(&rgb);
        let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
        let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
        if *de.value() < best.0 {
            best = (*de.value(), ansi);
        }
    }
    best.1
}

pub fn textcolor_for_bg(col: &Color) -> Color {
    let bg_lum = col.luminance();
    let contrast_black = if bg_lum>0.0 { (bg_lum+0.05)/0.05 } else { 0.05/(bg_lum+0.05) };
    let contrast_white = if 1.0>bg_lum { 1.05/(bg_lum+0.05) } else { (bg_lum+0.05)/1.05 };
    if contrast_black >= contrast_white {
        Color::new(0,0,0,1.0)
    } else {
        Color::new(255,255,255,1.0)
    }
}

pub fn find_exact_name(col: &Color) -> (String, bool) {
    for (name, hex) in crate::named::all_named_colors() {
        let c = try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b {
            return (name.to_string(), true);
        }
    }
    (String::new(), false)
}

pub fn find_similar_colors(col: &Color, n: usize) -> Vec<String> {
    let mut distances: Vec<(f64, String)> = Vec::new();
    for (name, hex) in distinct_colors_139() {
        let c = try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b { continue; }
        let (l1,a1,b1) = col.to_lab();
        let (l2,a2,b2) = c.to_lab();
        let d = ((l1-l2).powi(2)+(a1-a2).powi(2)+(b1-b2).powi(2)).sqrt();
        distances.push((d, name.to_string()));
    }
    distances.sort_by(|a,b| a.0.partial_cmp(&b.0).unwrap());
    distances.into_iter().take(n).map(|(_,name)| name).collect()
}

pub fn format_hsl_for_display(col: &Color) -> String {
    let (h,s,l) = col.to_hsl();
    if col.is_opaque() {
