pub fn format_color(col: &Color, fmt: &str, mode: crate::cli::ColorModeEffective, _is_tty: bool) -> String {
    let plain = match fmt {
        "rgb" => col.to_rgb_string(),
        "rgb-float" => col.to_rgb_float_string(),
        "rgb-r" => format!("{}", col.r),
        "rgb-g" => format!("{}", col.g),
        "rgb-b" => format!("{}", col.b),
        "hex" => col.to_hex(),
        "hsl" => {
            let (h,s,l) = col.to_hsl();
            if col.is_opaque() {
                format!("hsl({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, l*100.0)
            } else {
                format!("hsla({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, l*100.0, Color::format_alpha(col.alpha))
            }
        },
        "hsl-hue" => { let (h,_,_) = col.to_hsl(); format!("{}", h.round() as i32) },
        "hsl-saturation" => { let (_,s,_) = col.to_hsl(); format!("{:.4}", s) },
        "hsl-lightness" => { let (_,_,l) = col.to_hsl(); format!("{:.4}", l) },
        "hsv" => {
            let (h,s,v) = col.to_hsv();
            if col.is_opaque() {
                format!("hsv({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, v*100.0)
            } else {
                format!("hsva({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, v*100.0, Color::format_alpha(col.alpha))
            }
        },
        "hsv-hue" => { let (h,_,_) = col.to_hsv(); format!("{}", h.round() as i32) },
        "hsv-saturation" => { let (_,s,_) = col.to_hsv(); format!("{:.4}", s) },
        "hsv-value" => { let (_,_,v) = col.to_hsv(); format!("{:.4}", v) },
        "lch" => {
            let (l,c,h) = col.to_lch();
            if col.is_opaque() {
                format!("LCh({}, {}, {})", l.round() as i32, c.round() as i32, h.round() as i32)
            } else {
                format!("LCh({}, {}, {}, {})", l.round() as i32, c.round() as i32, h.round() as i32, Color::format_alpha(col.alpha))
            }
        },
        "lch-lightness" => { let (l,_,_) = col.to_lch(); format!("{:.2}", l) },
        "lch-chroma" => { let (_,c,_) = col.to_lch(); format!("{:.2}", c) },
        "lch-hue" => { let (_,_,h) = col.to_lch(); format!("{:.2}", h) },
        "oklch" => {
            let (l,c,h) = col.to_oklch();
            if col.is_opaque() {
                format!("OkLCh({:.4}, {:.4}, {:.4})", l,c,h)
            } else {
                format!("OkLCh({:.4}, {:.4}, {:.4}, {})", l,c,h, Color::format_alpha(col.alpha))
            }
        },
        "oklch-lightness" => { let (l,_,_) = col.to_oklch(); format!("{:.4}", l) },
        "oklch-chroma" => { let (_,c,_) = col.to_oklch(); format!("{:.4}", c) },
        "oklch-hue" => { let (_,_,h) = col.to_oklch(); format!("{:.4}", h) },
        "lab" => {
            let (l,a,b) = col.to_lab();
            if col.is_opaque() {
                format!("Lab({}, {}, {})", l.round() as i32, a.round() as i32, b.round() as i32)
            } else {
                format!("Lab({}, {}, {}, {})", l.round() as i32, a.round() as i32, b.round() as i32, Color::format_alpha(col.alpha))
            }
        },
        "lab-a" => { let (_,a,_) = col.to_lab(); format!("{:.2}", a) },
        "lab-b" => { let (_,_,b) = col.to_lab(); format!("{:.2}", b) },
        "oklab" => {
            let (l,a,b) = col.to_oklab();
            if col.is_opaque() {
                format!("OkLab({:.4}, {:.4}, {:.4})", l,a,b)
            } else {
                format!("OkLab({:.4}, {:.4}, {:.4}, {})", l,a,b, Color::format_alpha(col.alpha))
            }
        },
        "oklab-l" => { let (l,_,_) = col.to_oklab(); format!("{:.4}", l) },
        "oklab-a" => { let (_,a,_) = col.to_oklab(); format!("{:.4}", a) },
        "oklab-b" => { let (_,_,b) = col.to_oklab(); format!("{:.4}", b) },
        "luminance" => format!("{:.3}", col.luminance()),
        "brightness" => format!("{:.3}", col.brightness()),
        "ansi-8bit" => format!("\x1b[38;5;{}m", rgb_to_ansi8(col.r, col.g, col.b)),
        "ansi-24bit" => format!("\x1b[38;2;{};{};{}m", col.r, col.g, col.b),
        "ansi-8bit-value" => format!("{}", rgb_to_ansi8(col.r, col.g, col.b)),
        "ansi-8bit-escapecode" => format!("\x1b[38;5;{}m", rgb_to_ansi8(col.r, col.g, col.b)),
        "ansi-24bit-escapecode" => format!("\x1b[38;2;{};{};{}m", col.r, col.g, col.b),
        "cmyk" => {
            let (c,m,y,k) = col.to_cmyk();
            format!("cmyk({}, {}, {}, {})", (c*100.0).round() as i32, (m*100.0).round() as i32, (y*100.0).round() as i32, (k*100.0).round() as i32)
        },
        "name" => {
            let (exact, is_exact) = find_exact_name(col);
            if is_exact { exact } else {
                let mut best_name = "black".to_string();
                let mut best_dist = f64::MAX;
                for (n,hex) in distinct_colors_139() {
                    let c = try_parse_hex(hex).unwrap();
                    let (l1,a1,b1) = col.to_lab();
                    let (l2,a2,b2) = c.to_lab();
                    let d = ((l1-l2).powi(2)+(a1-a2).powi(2)+(b1-b2).powi(2)).sqrt();
                    if d<best_dist { best_dist=d; best_name=n.to_string(); }
                }
                best_name
            }
        },
        _ => col.to_hex(),
    };
    match mode {
        crate::cli::ColorModeEffective::Off => plain,
        crate::cli::ColorModeEffective::EightBit => {
            if fmt=="ansi-8bit-value" || fmt=="ansi-8bit-escapecode" || fmt=="ansi-24bit-escapecode" { plain } else {
                let fg = textcolor_for_bg(col);
                let fg_ansi = rgb_to_ansi8(fg.r, fg.g, fg.b);
                let bg_ansi = rgb_to_ansi8(col.r, col.g, col.b);
                format!("\x1b[38;5;{};48;5;{}m{}\x1b[0m", fg_ansi, bg_ansi, plain)
            }
        },
        crate::cli::ColorModeEffective::TwentyFourBit => {
            if fmt=="ansi-8bit-value" || fmt=="ansi-8bit-escapecode" || fmt=="ansi-24bit-escapecode" { plain } else {
                let fg = textcolor_for_bg(col);
                format!("\x1b[38;2;{};{};{};48;2;{};{};{}m{}\x1b[0m", fg.r, fg.g, fg.b, col.r, col.g, col.b, plain)
            }
        },
    }
}
