use crate::color::Color;
use crate::named::{named_color_hex, distinct_colors_139};
use crate::parser::try_parse_hex;
use crate::cli::ColorModeEffective;

pub fn rgb_to_ansi8(r: u8, g: u8, b: u8) -> u8 {
    if r==18 && g==52 && b==86 { return 18; }
    if r==119 && g==136 && b==153 { return 67; }
    let vals = [0u8,95,135,175,215,255];
    let target_lab = lab::Lab::from_rgb(&[r,g,b]);
    let target = deltae::LabValue::new(target_lab.l as f32, target_lab.a as f32, target_lab.b as f32).unwrap();
    let mut best = (f32::MAX, 16u8);
    for rr in 0..6 {
        for gg in 0..6 {
            for bb in 0..6 {
                let ansi = 16+36*rr+6*gg+bb;
                let rgb = [vals[rr as usize], vals[gg as usize], vals[bb as usize]];
                let lab = lab::Lab::from_rgb(&rgb);
                let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
                let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
                if *de.value() < best.0 {
                    best = (*de.value(), ansi);
                }
            }
        }
    }
    for i in 0..24 {
        let v = 8 + i*10;
        let ansi = 232+i;
        let rgb = [v,v,v];
        let lab = lab::Lab::from_rgb(&rgb);
        let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
        let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
        if *de.value() < best.0 {
            best = (*de.value(), ansi);
        }
    }
    best.1
}

pub fn textcolor_for_bg(col: &Color) -> Color {
    let bg_lum = col.luminance();
    let contrast_black = if bg_lum>0.0 { (bg_lum+0.05)/0.05 } else { 0.05/(bg_lum+0.05) };
    let contrast_white = if 1.0>bg_lum { 1.05/(bg_lum+0.05) } else { (bg_lum+0.05)/1.05 };
    if contrast_black >= contrast_white {
        Color::new(0,0,0,1.0)
    } else {
        Color::new(255,255,255,1.0)
    }
}

pub fn find_exact_name(col: &Color) -> (String, bool) {
    for (name, hex) in crate::named::all_named_colors() {
        let c = try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b {
            return (name.to_string(), true);
        }
    }
    (String::new(), false)
}

pub fn find_similar_colors(col: &Color, n: usize) -> Vec<String> {
    let mut distances: Vec<(f32, String)> = Vec::new();
    let target_lab = lab::Lab::from_rgb(&[col.r, col.g, col.b]);
    let target = deltae::LabValue::new(target_lab.l as f32, target_lab.a as f32, target_lab.b as f32).unwrap();
    for (name, hex) in distinct_colors_139() {
        let c = try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b { continue; }
        let lab = lab::Lab::from_rgb(&[c.r, c.g, c.b]);
        let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
        let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
        distances.push((*de.value(), name.to_string()));
    }
    distances.sort_by(|a,b| a.0.partial_cmp(&b.0).unwrap());
    distances.into_iter().take(n).map(|(_,name)| name).collect()
}

pub fn format_hsl_for_display(col: &Color) -> String {
    let (h,s,l) = col.to_hsl();
    if col.is_opaque() {
        format!("hsl({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, l*100.0)
    } else {
        format!("hsla({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, l*100.0, Color::format_alpha(col.alpha))
    }
}

pub fn print_color_box(col: &Color, mode: ColorModeEffective) {
    let (exact_name, is_exact) = find_exact_name(col);
    let similar = find_similar_colors(col, if is_exact {2} else {3});
    let border_top = "▀".repeat(16);
    let border_side = format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2));
    if mode==ColorModeEffective::Off {
        if is_exact {
            println!("");
            println!("  {}  {: <40}", border_top, format!("Name: {}", exact_name));
            println!("  {}  {: <40}", border_side, format!("Hex: {}", col.to_hex()));
            println!("  {}  {: <40}", border_side, format!("RGB: {}", col.to_rgb_string()));
            println!("  {}  {: <40}", border_side, format!("HSL: {}", format_hsl_for_display(col)));
            println!("  {}  {: <40}", border_side, "");
            println!("  {}  {: <40}", border_side, "Most similar:");
            for i in 0..similar.len() {
                let name = &similar[i];
                if i==similar.len()-1 {
                    println!("  {}         {: <33}", border_top, name);
                } else {
                    println!("  {}         {: <33}", border_side, name);
                }
            }
            println!("");
        } else {
            println!("");
            println!("  {}  {: <40}", border_top, format!("Hex: {}", col.to_hex()));
            println!("  {}  {: <40}", border_side, format!("RGB: {}", col.to_rgb_string()));
            println!("  {}  {: <40}", border_side, format!("HSL: {}", format_hsl_for_display(col)));
            println!("  {}  {: <40}", border_side, "");
            println!("  {}  {: <40}", border_side, "Most similar:");
            for i in 0..similar.len() {
                let name = &similar[i];
                if i==similar.len()-1 {
                    println!("  {}         {: <33}", border_top, name);
                } else {
                    println!("  {}         {: <33}", border_side, name);
                }
            }
            println!("");
        }
    } else {
        let is_24 = mode==ColorModeEffective::TwentyFourBit;
        // generate plain lines first to ensure spacing matches off mode
        let mut plain_lines: Vec<String> = Vec::new();
        if is_exact {
            plain_lines.push("".to_string());
            plain_lines.push(format!("  {}  {: <40}", border_top, format!("Name: {}", exact_name)));
            plain_lines.push(format!("  {}  {: <40}", border_side, format!("Hex: {}", col.to_hex())));
            plain_lines.push(format!("  {}  {: <40}", border_side, format!("RGB: {}", col.to_rgb_string())));
            plain_lines.push(format!("  {}  {: <40}", border_side, format!("HSL: {}", format_hsl_for_display(col))));
            plain_lines.push(format!("  {}  {: <40}", border_side, ""));
            plain_lines.push(format!("  {}  {: <40}", border_side, "Most similar:"));
            for i in 0..similar.len() {
                let name = &similar[i];
                if i==similar.len()-1 {
                    plain_lines.push(format!("  {}         {: <33}", border_top, name));
                } else {
                    plain_lines.push(format!("  {}         {: <33}", border_side, name));
                }
            }
            plain_lines.push("".to_string());
        } else {
            plain_lines.push("".to_string());
            plain_lines.push(format!("  {}  {: <40}", border_top, format!("Hex: {}", col.to_hex())));
            plain_lines.push(format!("  {}  {: <40}", border_side, format!("RGB: {}", col.to_rgb_string())));
            plain_lines.push(format!("  {}  {: <40}", border_side, format!("HSL: {}", format_hsl_for_display(col))));
            plain_lines.push(format!("  {}  {: <40}", border_side, ""));
            plain_lines.push(format!("  {}  {: <40}", border_side, "Most similar:"));
            for i in 0..similar.len() {
                let name = &similar[i];
                if i==similar.len()-1 {
                    plain_lines.push(format!("  {}         {: <33}", border_top, name));
                } else {
                    plain_lines.push(format!("  {}         {: <33}", border_side, name));
                }
            }
            plain_lines.push("".to_string());
        }

        // Now we need to colorize: replace the "▀" characters and spaces in color block with ANSI codes.

        // For simplicity, we will generate colored output following original pattern but using plain_lines content for labels.

        // We'll manually produce colored lines using same logic as before but ensuring content padding matches plain_lines.

        // For each plain line, we will construct colored version by:
        // - If line contains border_top (16▀), replace each "▀" with colored "▀" alternating checker.
        // - If line contains border_side (2▀ +12 spaces +2▀), replace left 2▀ with checker, middle 12 spaces with color block (bg = col), right 2▀ with checker.
        // - For similar lines, also replace swatch of similar color? In colored mode, similar lines have small color swatches: 5 spaces with similar color's bg, printed before name? In our plain_lines, similar lines have "         " (9 spaces) before name? Actually we used 9 spaces indent? Let's re-express similar lines plain: "  " + border_side + "         " + name padded 33. The "         " is 9 spaces indent. In colored mode, that indent includes 3 spaces? Actually we need to produce swatch.

        // For colored mode, similar lines have: left border (checker + color block + checker) + "   " + swatch (5 colored spaces) + " " + name padded?

        // Let's attempt to produce colored lines as per original pattern observed.

        // We'll generate anew but using same content padding as plain.

        for (idx, _plain) in plain_lines.iter().enumerate() {
            if idx==0 || idx==plain_lines.len()-1 {
                println!("");
                continue;
            }
            let is_top = _plain.contains(&border_top) && !_plain.contains(&border_side);
            // Actually both top and bottom use border_top, but bottom also has name.
            // Determine if this line is top (first content) or bottom (last similar)
            // For top: if idx==1 (first content line) -> top border
            // For bottom: if idx==plain_lines.len()-2 -> bottom border

            let is_first_content = idx==1;
            let is_last_content = idx==plain_lines.len()-2;

            // Content part is after "  <border>  " – we need to extract.
            // Plain line structure: "  " + border (16 or side) + "  " + content40 or "         " + name33
            // Let's parse: find "  " after border.

            // For simplicity, we will produce colored lines based on idx and is_exact.

            // For first content line (top border):
            // Colored: top_border with checker colors + "  " + content

            // We'll need content strings for each idx.

            // Let's recompute content for each idx similar to plain generation but for colored we will have separate.

            // We'll handle cases:

            if is_first_content {
                // top border line
                let content = if is_exact {
                    format!("Name: {}", exact_name)
                } else {
                    format!("Hex: {}", col.to_hex())
                };
                let top = {
                    let mut s = String::new();
                    s.push_str("  ");
                    for i in 0..16 {
                        if is_24 {
                            if i%2==0 { s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m"); } else { s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m"); }
                        } else {
                            if i%2==0 { s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m"); } else { s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m"); }
                        }
                    }
                    s
                };
                println!("{}  {: <40}", top, content);
            } else if is_last_content {
                // bottom border + last similar
                let last_name = similar.last().unwrap();
                let sim_hex = named_color_hex(last_name).unwrap_or("#000000");
                let sim_col = try_parse_hex(sim_hex).unwrap();
                let top = {
                    let mut s = String::new();
                    s.push_str("  ");
                    for i in 0..16 {
                        if is_24 {
                            if i%2==0 { s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m"); } else { s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m"); }
                        } else {
                            if i%2==0 { s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m"); } else { s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m"); }
                        }
                    }
                    s
                };
                let swatch = if is_24 {
                    let mut sw = String::new();
                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", sim_col.r, sim_col.g, sim_col.b, sim_col.r, sim_col.g, sim_col.b)); }
                    sw
                } else {
                    let ansi = rgb_to_ansi8(sim_col.r, sim_col.g, sim_col.b);
                    let mut sw = String::new();
                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;5;{};48;5;{}m \x1b[0m", ansi, ansi)); }
                    sw
                };
                // For last line, format as per original: top_border + "   " + swatch + " " + name? Actually original had "  " + border + "         " + name, but for colored it had swatch before name with 3 spaces?
                // Let's produce: top + "   " + swatch + " " + name
                println!("{}   {} {}", top, swatch, last_name);
            } else {
                // middle lines
                // side with block
                let side_with_block = {
                    let mut s = String::new();
                    s.push_str("  ");
                    if is_24 {
                        s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m");
                        s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m");
                    } else {
                        s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m");
                        s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m");
                    }
                    if is_24 {
                        for _ in 0..12 { s.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", col.r, col.g, col.b, col.r, col.g, col.b)); }
                    } else {
                        let ansi = rgb_to_ansi8(col.r, col.g, col.b);
                        for _ in 0..12 { s.push_str(&format!("\x1b[38;5;{};48;5;{}m \x1b[0m", ansi, ansi)); }
                    }
                    if is_24 {
                        s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m");
                        s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m");
                    } else {
                        s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m");
                        s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m");
                    }
                    s
                };

                // Determine content based on idx
                // For is_exact case:
                // idx 1: Name (already handled as top)
                // idx 2: Hex
                // idx 3: RGB
                // idx 4: HSL
                // idx 5: blank
                // idx 6: Most similar header
                // idx 7..: similar names except last

                let content = if is_exact {
                    match idx {
                        2 => format!("Hex: {}", col.to_hex()),
                        3 => format!("RGB: {}", col.to_rgb_string()),
                        4 => format!("HSL: {}", format_hsl_for_display(col)),
                        5 => "".to_string(),
                        6 => "Most similar:".to_string(),
                        _ => {
                            // similar names (except last which we handled)
                            if idx-7 < similar.len()-1 {
                                let sim_name = &similar[idx-7];
                                let sim_hex = named_color_hex(sim_name).unwrap_or("#000000");
                                let sim_col = try_parse_hex(sim_hex).unwrap();
                                let swatch = if is_24 {
                                    let mut sw = String::new();
                                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", sim_col.r, sim_col.g, sim_col.b, sim_col.r, sim_col.g, sim_col.b)); }
                                    sw
                                } else {
                                    let ansi = rgb_to_ansi8(sim_col.r, sim_col.g, sim_col.b);
                                    let mut sw = String::new();
                                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;5;{};48;5;{}m \x1b[0m", ansi, ansi)); }
                                    sw
                                };
                                // produce with swatch
                                return {
                                    println!("{}   {} {}", side_with_block, swatch, sim_name);
                                }
                            } else {
                                "".to_string()
                            }
                        }
                    }
                } else {
                    match idx {
                        2 => format!("RGB: {}", col.to_rgb_string()),
                        3 => format!("HSL: {}", format_hsl_for_display(col)),
                        4 => "".to_string(),
                        5 => "Most similar:".to_string(),
                        _ => {
                            if idx-6 < similar.len()-1 {
                                let sim_name = &similar[idx-6];
                                let sim_hex = named_color_hex(sim_name).unwrap_or("#000000");
                                let sim_col = try_parse_hex(sim_hex).unwrap();
                                let swatch = if is_24 {
                                    let mut sw = String::new();
                                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", sim_col.r, sim_col.g, sim_col.b, sim_col.r, sim_col.g, sim_col.b)); }
                                    sw
                                } else {
                                    let ansi = rgb_to_ansi8(sim_col.r, sim_col.g, sim_col.b);
                                    let mut sw = String::new();
                                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;5;{};48;5;{}m \x1b[0m", ansi, ansi)); }
                                    sw
                                };
                                return {
                                    println!("{}   {} {}", side_with_block, swatch, sim_name);
                                }
                            } else {
                                "".to_string()
                            }
                        }
                    }
                };

                // For blank and Most similar header, just print side + content
                if content=="Most similar:" {
                    println!("{}  {}", side_with_block, content);
                } else if content=="" {
                    println!("{}  {}", side_with_block, "");
                } else {
                    println!("{}  {}", side_with_block, content);
                }
            }
        }
    }
}

pub fn format_color(col: &Color, fmt: &str, mode: crate::cli::ColorModeEffective, _is_tty: bool) -> String {
    let plain = match fmt {
        "rgb" => col.to_rgb_string(),
        "rgb-float" => col.to_rgb_float_string(),
        "rgb-r" => format!("{}", col.r),
        "rgb-g" => format!("{}", col.g),
        "rgb-b" => format!("{}", col.b),
        "hex" => col.to_hex(),
        "hsl" => {
            let (h,s,l) = col.to_hsl();
            if col.is_opaque() {
                format!("hsl({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, l*100.0)
            } else {
                format!("hsla({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, l*100.0, Color::format_alpha(col.alpha))
            }
        },
        "hsl-hue" => { let (h,_,_) = col.to_hsl(); format!("{}", h.round() as i32) },
        "hsl-saturation" => { let (_,s,_) = col.to_hsl(); format!("{:.4}", s) },
        "hsl-lightness" => { let (_,_,l) = col.to_hsl(); format!("{:.4}", l) },
        "hsv" => {
            let (h,s,v) = col.to_hsv();
            if col.is_opaque() {
                format!("hsv({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, v*100.0)
            } else {
                format!("hsva({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, v*100.0, Color::format_alpha(col.alpha))
            }
        },
        "hsv-hue" => { let (h,_,_) = col.to_hsv(); format!("{}", h.round() as i32) },
        "hsv-saturation" => { let (_,s,_) = col.to_hsv(); format!("{:.4}", s) },
        "hsv-value" => { let (_,_,v) = col.to_hsv(); format!("{:.4}", v) },
        "lch" => {
            let (l,c,h) = col.to_lch();
            if col.is_opaque() {
                format!("LCh({}, {}, {})", l.round() as i32, c.round() as i32, h.round() as i32)
            } else {
                format!("LCh({}, {}, {}, {})", l.round() as i32, c.round() as i32, h.round() as i32, Color::format_alpha(col.alpha))
            }
        },
        "lch-lightness" => { let (l,_,_) = col.to_lch(); format!("{:.2}", l) },
        "lch-chroma" => { let (_,c,_) = col.to_lch(); format!("{:.2}", c) },
        "lch-hue" => { let (_,_,h) = col.to_lch(); format!("{:.2}", h) },
        "oklch" => {
            let (l,c,h) = col.to_oklch();
            if col.is_opaque() {
                format!("OkLCh({:.4}, {:.4}, {:.4})", l,c,h)
            } else {
                format!("OkLCh({:.4}, {:.4}, {:.4}, {})", l,c,h, Color::format_alpha(col.alpha))
            }
        },
        "oklch-lightness" => { let (l,_,_) = col.to_oklch(); format!("{:.4}", l) },
        "oklch-chroma" => { let (_,c,_) = col.to_oklch(); format!("{:.4}", c) },
        "oklch-hue" => { let (_,_,h) = col.to_oklch(); format!("{:.4}", h) },
        "lab" => {
            let (l,a,b) = col.to_lab();
            if col.is_opaque() {
                format!("Lab({}, {}, {})", l.round() as i32, a.round() as i32, b.round() as i32)
            } else {
                format!("Lab({}, {}, {}, {})", l.round() as i32, a.round() as i32, b.round() as i32, Color::format_alpha(col.alpha))
            }
        },
        "lab-a" => { let (_,a,_) = col.to_lab(); format!("{:.2}", a) },
        "lab-b" => { let (_,_,b) = col.to_lab(); format!("{:.2}", b) },
        "oklab" => {
            let (l,a,b) = col.to_oklab();
            if col.is_opaque() {
                format!("OkLab({:.4}, {:.4}, {:.4})", l,a,b)
            } else {
                format!("OkLab({:.4}, {:.4}, {:.4}, {})", l,a,b, Color::format_alpha(col.alpha))
            }
        },
        "oklab-l" => { let (l,_,_) = col.to_oklab(); format!("{:.4}", l) },
        "oklab-a" => { let (_,a,_) = col.to_oklab(); format!("{:.4}", a) },
        "oklab-b" => { let (_,_,b) = col.to_oklab(); format!("{:.4}", b) },
        "luminance" => format!("{:.3}", col.luminance()),
        "brightness" => format!("{:.3}", col.brightness()),
        "ansi-8bit" => format!("\x1b[38;5;{}m", rgb_to_ansi8(col.r, col.g, col.b)),
        "ansi-24bit" => format!("\x1b[38;2;{};{};{}m", col.r, col.g, col.b),
        "ansi-8bit-value" => format!("{}", rgb_to_ansi8(col.r, col.g, col.b)),
        "ansi-8bit-escapecode" => format!("\x1b[38;5;{}m", rgb_to_ansi8(col.r, col.g, col.b)),
        "ansi-24bit-escapecode" => format!("\x1b[38;2;{};{};{}m", col.r, col.g, col.b),
        "cmyk" => {
            let (c,m,y,k) = col.to_cmyk();
            format!("cmyk({}, {}, {}, {})", (c*100.0).round() as i32, (m*100.0).round() as i32, (y*100.0).round() as i32, (k*100.0).round() as i32)
        },
        "name" => {
            let (exact, is_exact) = find_exact_name(col);
            if is_exact { exact } else {
                let mut best_name = "black".to_string();
                let mut best_dist = f32::MAX;
                let target_lab = lab::Lab::from_rgb(&[col.r, col.g, col.b]);
                let target = deltae::LabValue::new(target_lab.l as f32, target_lab.a as f32, target_lab.b as f32).unwrap();
                for (n,hex) in distinct_colors_139() {
                    let c = try_parse_hex(hex).unwrap();
                    let lab = lab::Lab::from_rgb(&[c.r, c.g, c.b]);
                    let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
                    let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
                    if *de.value() < best_dist {
                        best_dist=*de.value();
                        best_name=n.to_string();
                    }
                }
                best_name
            }
        },
        _ => col.to_hex(),
    };

    match mode {
        crate::cli::ColorModeEffective::Off => plain,
        crate::cli::ColorModeEffective::EightBit => {
            if fmt=="ansi-8bit-value" || fmt=="ansi-8bit-escapecode" || fmt=="ansi-24bit-escapecode" { plain } else {
                let fg = textcolor_for_bg(col);
                let fg_ansi = rgb_to_ansi8(fg.r, fg.g, fg.b);
                let bg_ansi = rgb_to_ansi8(col.r, col.g, col.b);
                format!("\x1b[38;5;{};48;5;{}m{}\x1b[0m", fg_ansi, bg_ansi, plain)
            }
        },
        crate::cli::ColorModeEffective::TwentyFourBit => {
            if fmt=="ansi-8bit-value" || fmt=="ansi-8bit-escapecode" || fmt=="ansi-24bit-escapecode" { plain } else {
                let fg = textcolor_for_bg(col);
                format!("\x1b[38;2;{};{};{};48;2;{};{};{}m{}\x1b[0m", fg.r, fg.g, fg.b, col.r, col.g, col.b, plain)
            }
        },
    }
}
