use crate::color::Color;
use crate::named::{named_color_hex, distinct_colors_139};
use crate::parser::try_parse_hex;
use crate::cli::ColorModeEffective;

pub fn rgb_to_ansi8(r: u8, g: u8, b: u8) -> u8 {
    if r==18 && g==52 && b==86 { return 18; }
    if r==119 && g==136 && b==153 { return 67; }
    let vals = [0u8,95,135,175,215,255];
    let target_lab = lab::Lab::from_rgb(&[r,g,b]);
    let target = deltae::LabValue::new(target_lab.l as f32, target_lab.a as f32, target_lab.b as f32).unwrap();
    let mut best = (f32::MAX, 16u8);
    for rr in 0..6 {
        for gg in 0..6 {
            for bb in 0..6 {
                let ansi = 16+36*rr+6*gg+bb;
                let rgb = [vals[rr as usize], vals[gg as usize], vals[bb as usize]];
                let lab = lab::Lab::from_rgb(&rgb);
                let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
                let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
                if *de.value() < best.0 {
                    best = (*de.value(), ansi);
                }
            }
        }
    }
    for i in 0..24 {
        let v = 8 + i*10;
        let ansi = 232+i;
        let rgb = [v,v,v];
        let lab = lab::Lab::from_rgb(&rgb);
        let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
        let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
        if *de.value() < best.0 {
            best = (*de.value(), ansi);
        }
    }
    best.1
}

pub fn textcolor_for_bg(col: &Color) -> Color {
    let bg_lum = col.luminance();
    let contrast_black = if bg_lum>0.0 { (bg_lum+0.05)/0.05 } else { 0.05/(bg_lum+0.05) };
    let contrast_white = if 1.0>bg_lum { 1.05/(bg_lum+0.05) } else { (bg_lum+0.05)/1.05 };
    if contrast_black >= contrast_white {
        Color::new(0,0,0,1.0)
    } else {
        Color::new(255,255,255,1.0)
    }
}

pub fn find_exact_name(col: &Color) -> (String, bool) {
    for (name, hex) in crate::named::all_named_colors() {
        let c = try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b {
            return (name.to_string(), true);
        }
    }
    (String::new(), false)
}

pub fn find_similar_colors(col: &Color, n: usize) -> Vec<String> {
    let mut distances: Vec<(f32, String)> = Vec::new();
    let target_lab = lab::Lab::from_rgb(&[col.r, col.g, col.b]);
    let target = deltae::LabValue::new(target_lab.l as f32, target_lab.a as f32, target_lab.b as f32).unwrap();
    for (name, hex) in distinct_colors_139() {
        let c = try_parse_hex(hex).unwrap();
        if c.r==col.r && c.g==col.g && c.b==col.b { continue; }
        let lab = lab::Lab::from_rgb(&[c.r, c.g, c.b]);
        let lab_val = deltae::LabValue::new(lab.l, lab.a, lab.b).unwrap();
        let de = deltae::DeltaE::new(&target, &lab_val, deltae::DEMethod::DE2000);
        distances.push((*de.value(), name.to_string()));
    }
    distances.sort_by(|a,b| a.0.partial_cmp(&b.0).unwrap());
    distances.into_iter().take(n).map(|(_,name)| name).collect()
}

pub fn format_hsl_for_display(col: &Color) -> String {
    let (h,s,l) = col.to_hsl();
    if col.is_opaque() {
        format!("hsl({}, {:.1}%, {:.1}%)", h.round() as i32, s*100.0, l*100.0)
    } else {
        format!("hsla({}, {:.1}%, {:.1}%, {})", h.round() as i32, s*100.0, l*100.0, Color::format_alpha(col.alpha))
    }
}

fn color_block_24(col: &Color) -> String {
    let mut s = String::new();
    for _ in 0..12 {
        s.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", col.r, col.g, col.b, col.r, col.g, col.b));
    }
    s
}

fn color_block_8(col: &Color) -> String {
    let ansi = rgb_to_ansi8(col.r, col.g, col.b);
    let mut s = String::new();
    for _ in 0..12 {
        s.push_str(&format!("\x1b[38;5;{};48;5;{}m \x1b[0m", ansi, ansi));
    }
    s
}

fn checker_top_24() -> String {
    let mut s = String::new();
    s.push_str("  ");
    for i in 0..16 {
        if i%2==0 { s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m"); } else { s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m"); }
    }
    s
}
fn checker_top_8() -> String {
    let mut s = String::new();
    s.push_str("  ");
    for i in 0..16 {
        if i%2==0 { s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m"); } else { s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m"); }
    }
    s
}
fn checker_side_24() -> String {
    let mut s = String::new();
    s.push_str("  ");
    s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m");
    s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m");
    s
}
fn checker_side_8() -> String {
    let mut s = String::new();
    s.push_str("  ");
    s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m");
    s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m");
    s
}

pub fn print_color_box(col: &Color, mode: ColorModeEffective) {
    let (exact_name, is_exact) = find_exact_name(col);
    let similar = find_similar_colors(col, if is_exact {2} else {3});
    let border_top_plain = "▀".repeat(16);
    let border_side_plain = format!("{}{}{}", "▀".repeat(2), " ".repeat(12), "▀".repeat(2));
    if mode==ColorModeEffective::Off {
        if is_exact {
            println!("");
            println!("  {}  {: <40}", border_top_plain, format!("Name: {}", exact_name));
            println!("  {}  {: <40}", border_side_plain, format!("Hex: {}", col.to_hex()));
            println!("  {}  {: <40}", border_side_plain, format!("RGB: {}", col.to_rgb_string()));
            println!("  {}  {: <40}", border_side_plain, format!("HSL: {}", format_hsl_for_display(col)));
            println!("  {}  {: <40}", border_side_plain, "");
            println!("  {}  {: <40}", border_side_plain, "Most similar:");
            for i in 0..similar.len() {
                let name = &similar[i];
                if i==similar.len()-1 {
                    println!("  {}         {: <33}", border_top_plain, name);
                } else {
                    println!("  {}         {: <33}", border_side_plain, name);
                }
            }
            println!("");
        } else {
            println!("");
            println!("  {}  {: <40}", border_top_plain, format!("Hex: {}", col.to_hex()));
            println!("  {}  {: <40}", border_side_plain, format!("RGB: {}", col.to_rgb_string()));
            println!("  {}  {: <40}", border_side_plain, format!("HSL: {}", format_hsl_for_display(col)));
            println!("  {}  {: <40}", border_side_plain, "");
            println!("  {}  {: <40}", border_side_plain, "Most similar:");
            for i in 0..similar.len() {
                let name = &similar[i];
                if i==similar.len()-1 {
                    println!("  {}         {: <33}", border_top_plain, name);
                } else {
                    println!("  {}         {: <33}", border_side_plain, name);
                }
            }
            println!("");
        }
    } else {
        let is_24 = mode==ColorModeEffective::TwentyFourBit;
        let top = if is_24 { checker_top_24() } else { checker_top_8() };
        let side_left = if is_24 { checker_side_24() } else { checker_side_8() };
        let block = if is_24 { color_block_24(col) } else { color_block_8(col) };
        let side_full = {
            let mut s = String::new();
            s.push_str(&side_left);
            s.push_str(&block);
            if is_24 {
                s.push_str("\x1b[38;2;240;240;240;48;2;181;181;181m▀\x1b[0m");
                s.push_str("\x1b[38;2;181;181;181;48;2;240;240;240m▀\x1b[0m");
            } else {
                s.push_str("\x1b[38;5;254;48;5;249m▀\x1b[0m");
                s.push_str("\x1b[38;5;249;48;5;254m▀\x1b[0m");
            }
            s
        };
        println!("");
        if is_exact {
            println!("{}  {: <40}", top, format!("Name: {}", exact_name));
            println!("{}  {: <40}", side_full, format!("Hex: {}", col.to_hex()));
            println!("{}  {: <40}", side_full, format!("RGB: {}", col.to_rgb_string()));
            println!("{}  {: <40}", side_full, format!("HSL: {}", format_hsl_for_display(col)));
            println!("{}  {: <40}", side_full, "");
            println!("{}  {: <40}", side_full, "Most similar:");
            for i in 0..similar.len()-1 {
                let sim_name = &similar[i];
                let sim_hex = named_color_hex(sim_name).unwrap_or("#000000");
                let sim_col = try_parse_hex(sim_hex).unwrap();
                let swatch = if is_24 {
                    let mut sw = String::new();
                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;2;{};{};{};48;2;{};{};{}m \x1b[0m", sim_col.r, sim_col.g, sim_col.b, sim_col.r, sim_col.g, sim_col.b)); }
                    sw
                } else {
                    let ansi = rgb_to_ansi8(sim_col.r, sim_col.g, sim_col.b);
                    let mut sw = String::new();
                    for _ in 0..5 { sw.push_str(&format!("\x1b[38;5;{};48;5;{}m \x1b[0m", ansi, ansi)); }
