pub fn mix_colors(a: &Color, b: &Color, fraction: f64, colorspace: &str) -> Color {
    match colorspace.to_lowercase().as_str() {
        "rgb" => {
            let r = (a.r as f64 * fraction + b.r as f64 * (1.0-fraction)).round() as u8;
            let g = (a.g as f64 * fraction + b.g as f64 * (1.0-fraction)).round() as u8;
            let b_ = (a.b as f64 * fraction + b.b as f64 * (1.0-fraction)).round() as u8;
            let alpha = a.alpha * fraction + b.alpha * (1.0-fraction);
            Color::new(r,g,b_,alpha)
        },
        "hsl" => {
            let (h1,s1,l1) = a.to_hsl();
            let (h2,s2,l2) = b.to_hsl();
            let mut delta = h2 - h1;
            if delta > 180.0 { delta -= 360.0; }
            if delta < -180.0 { delta += 360.0; }
            let h = h1 + delta*(1.0-fraction);
            let s = s1*fraction + s2*(1.0-fraction);
            let l = l1*fraction + l2*(1.0-fraction);
            let alpha = a.alpha*fraction + b.alpha*(1.0-fraction);
            Color::from_hsl(h, s, l, alpha)
